$string['settings:xai_proxy_url'] = 'xAI Realtime ਪ੍ਰੌਕਸੀ URL';
$string['settings:xai_proxy_url_desc'] = '[[tutorshort]] xAI Realtime ਪ੍ਰੌਕਸੀ ਸੇਵਾ ਦਾ ਜਨਤਕ wss URL (ਉਦਾਹਰਨ ਲਈ wss://voice.example.com/xai-rt/rt)। ਜਦੋਂ ਇਹ JWT ਗੁਪਤ ਕੁੰਜੀ ਨਾਲ ਸੈੱਟ ਹੁੰਦਾ ਹੈ, ਤਾਂ xAI ਆਵਾਜ਼ ਪ੍ਰੌਕਸੀ ਰਾਹੀਂ ਜਾਂਦੀ ਹੈ ਅਤੇ ਮਾਸਟਰ xAI API ਕੁੰਜੀ ਕਦੇ ਬ੍ਰਾਊਜ਼ਰ ਤੱਕ ਨਹੀਂ ਪਹੁੰਚਦੀ। ਸਿੱਧੇ ਕਨੈਕਸ਼ਨ ਉੱਤੇ ਫਾਲਬੈਕ ਲਈ ਖਾਲੀ ਛੱਡੋ (ਉਤਪਾਦਨ ਲਈ ਸਿਫਾਰਸ਼ ਨਹੀਂ)।';
$string['settings:xai_proxy_jwt_secret'] = 'xAI Realtime ਪ੍ਰੌਕਸੀ JWT ਗੁਪਤ ਕੁੰਜੀ';
$string['settings:xai_proxy_jwt_secret_desc'] = 'xAI Realtime ਪ੍ਰੌਕਸੀ ਲਈ ਥੋੜ੍ਹੇ-ਜੀਵਨ ਵਾਲੇ ਸੈਸ਼ਨ ਟੋਕਨ ਉੱਤੇ ਦਸਤਖਤ ਕਰਨ ਲਈ ਵਰਤੀ ਜਾਣ ਵਾਲੀ HS256 ਸਾਂਝੀ ਗੁਪਤ ਕੁੰਜੀ। ਇਹ Cloudflare Worker ਉੱਤੇ MOODLE_JWT_SECRET ਨਾਲ ਮੇਲ ਖਾਣੀ ਚਾਹੀਦੀ ਹੈ। ਸਮੇਂ-ਸਮੇਂ ਉੱਤੇ ਘੁਮਾਓ।';
$string['admin:vendor_dpa:title'] = '{$a} — ਵਿਕਰੇਤਾ DPA ਸਥਿਤੀ';
$string['admin:vendor_dpa:intro'] = 'ਹਰ AI ਪ੍ਰਦਾਤਾ ਡਰਾਈਵਰ ਲਈ ਟਰੇਨਿੰਗ ਆਪਟ-ਆਊਟ, DPA ਅਤੇ ਧਾਰਨ ਸਥਿਤੀ। ਆਪਣੀ ਸਾਈਟ ਉੱਤੇ ਕਿਹੜੇ ਡਰਾਈਵਰ ਯੋਗ ਕਰਨੇ ਹਨ ਇਹ ਫੈਸਲਾ ਕਰਨ ਲਈ ਇਸ ਦੀ ਵਰਤੋਂ ਕਰੋ। Tier 2 ਅਤੇ ਉੱਚ ਰੂਟਿੰਗ ਲਈ ਦਸਤਖਤ ਕੀਤੇ DPA ਅਤੇ ਇਕਰਾਰਨਾਮਾ ਟਰੇਨਿੰਗ ਆਪਟ-ਆਊਟ ਦੀ ਲੋੜ ਹੈ।';
$string['admin:vendor_dpa:maintenance_note'] = 'ਇਹ ਟੇਬਲ classes/vendor_registry.php ਵਿੱਚ ਰੱਖਿਆ ਜਾਂਦਾ ਹੈ। ਜਦੋਂ ਕਿਸੇ ਵਿਕਰੇਤਾ ਦੇ ToS ਵਿੱਚ ਤਬਦੀਲੀ ਆਉਂਦੀ ਹੈ ਤਾਂ ਇਸ ਨੂੰ ਅਪਡੇਟ ਕਰੋ।';
$string['settings:contact_email'] = 'ਸੰਪਰਕ ਈਮੇਲ';
$string['settings:contact_email_desc'] = 'General contact email shown on the learner facing privacy notice under "Contact". Defaults to contact@saylor.org. Leave empty to hide the line.';
