// v4.4.0: course-page CSP setting.
$string['settings:csp_course_pages_mode'] = 'ਕੋਰਸ-ਪੇਜ Content-Security-Policy';
$string['settings:csp_course_pages_mode_desc'] = 'ਉਹਨਾਂ ਕੋਰਸ ਪੇਜਾਂ ਉੱਤੇ ਵਿਕਲਪਿਕ CSP ਹੈਡਰ ਜਿੱਥੇ AI ਕੋਰਸ ਸਹਾਇਕ ਵਿਜੇਟ ਸਰਗਰਮ ਹੈ। <strong>ਬੰਦ</strong>: ਕੋਈ ਹੈਡਰ ਨਹੀਂ (ਡਿਫ਼ਾਲਟ)। <strong>ਸਿਰਫ਼-ਰਿਪੋਰਟ</strong>: <code>Content-Security-Policy-Report-Only</code> ਭੇਜੋ — ਬ੍ਰਾਊਜ਼ਰ ਉਲੰਘਣਾਵਾਂ ਦਰਜ ਕਰਦੇ ਹਨ ਪਰ ਰੋਕਦੇ ਨਹੀਂ। ਇੱਕ ਹਫ਼ਤੇ ਦੀ ਨਿਗਰਾਨੀ ਲਈ ਲਾਭਦਾਇਕ। <strong>ਲਾਗੂ ਕਰੋ</strong>: <code>Content-Security-Policy</code> ਭੇਜੋ — ਬ੍ਰਾਊਜ਼ਰ ਮਨਜ਼ੂਰੀ-ਸੂਚੀ ਤੋਂ ਬਾਹਰਲੇ iframe ਸਰੋਤ, fetch ਅਤੇ ਹੋਰ ਜੋਖਮ ਭਰੇ ਲੋਡ ਰੋਕ ਦਿੰਦੇ ਹਨ। ਇਹ ਸਾਈਟ ਦੀ Additional HTML ਸੰਰਚਨਾ ਵਿੱਚ ਚਿਪਕਾਈਆਂ ਮਨਮਰਜ਼ੀ ਦੀਆਂ ਸਕ੍ਰਿਪਟਾਂ ਦੇ ਅਸਰ ਨੂੰ ਸੀਮਤ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ (2026-04-29 ਦੀ IBL AI / Raison ਘਟਨਾ)। ਇਸ ਦਾ [[tutorshort]] ਦੇ ਐਂਡਪੌਇੰਟਾਂ ਉੱਤੇ ਕੋਈ ਅਸਰ ਨਹੀਂ ਪੈਂਦਾ, ਜੋ ਹਮੇਸ਼ਾ ਇਸ ਤੋਂ ਸਖ਼ਤ CSP ਭੇਜਦੇ ਹਨ।';
$string['settings:csp_mode_off'] = 'ਬੰਦ (ਕੋਰਸ ਪੇਜਾਂ ਉੱਤੇ ਕੋਈ ਹੈਡਰ ਨਹੀਂ)';
$string['settings:csp_mode_report_only'] = 'ਸਿਰਫ਼-ਰਿਪੋਰਟ (ਉਲੰਘਣਾਵਾਂ ਦਰਜ ਕਰੋ, ਰੋਕੋ ਨਾ)';
$string['settings:csp_mode_enforce'] = 'ਲਾਗੂ ਕਰੋ (ਮਨਜ਼ੂਰੀ-ਸੂਚੀ ਤੋਂ ਬਾਹਰਲੇ ਲੋਡ ਰੋਕੋ)';
// v4.5.0: site-wide pedagogy defaults.
$string['settings:pedagogy_defaults_heading'] = 'ਸਿੱਖਿਆ-ਸ਼ਾਸਤਰ ਡਿਫ਼ਾਲਟ';
$string['settings:pedagogy_defaults_heading_desc'] = 'ਹਰ ਸਿੱਖਿਆ-ਸ਼ਾਸਤਰ ਵਿਸ਼ੇਸ਼ਤਾ ਲਈ ਸਾਈਟ-ਵਿਆਪੀ ਡਿਫ਼ਾਲਟ ਸਥਿਤੀ। ਇੱਥੇ ਕੋਈ ਵਿਸ਼ੇਸ਼ਤਾ ਚਾਲੂ ਕਰੋ ਅਤੇ ਹਰ ਕੋਰਸ ਇਸ ਨੂੰ ਵਿਰਸੇ ਵਿੱਚ ਲੈ ਲੈਂਦਾ ਹੈ, ਜਦੋਂ ਤੱਕ ਉਸ ਕੋਰਸ ਦੇ [[tutorshort]] ਕੋਰਸ ਸੈਟਿੰਗਾਂ ਪੇਜ ਉੱਤੇ ਕੋਈ ਸਪਸ਼ਟ ਓਵਰਰਾਈਡ (ਜ਼ਬਰਦਸਤੀ ਚਾਲੂ / ਜ਼ਬਰਦਸਤੀ ਬੰਦ) ਨਾ ਹੋਵੇ। v4.5.0 ਵਿੱਚ ਅੱਪਗ੍ਰੇਡ ਕਰਨ ਉੱਤੇ, ਹਰ ਉਹ ਪ੍ਰਤੀ-ਕੋਰਸ "ਜ਼ਬਰਦਸਤੀ ਬੰਦ" ਓਵਰਰਾਈਡ ਸਾਫ਼ ਕਰ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ ਜੋ ਪੁਰਾਣੇ ਡਿਫ਼ਾਲਟ-ਬੰਦ ਮੁੱਲ <code>0</code> ਉੱਤੇ ਸੈੱਟ ਸੀ, ਤਾਂ ਜੋ ਨਵੇਂ ਗਲੋਬਲ ਡਿਫ਼ਾਲਟ ਸਾਫ਼-ਸੁਥਰੇ ਢੰਗ ਨਾਲ ਲਾਗੂ ਹੋਣ। ਡਿਫ਼ਾਲਟ ਬੰਦ — v4.4.x ਤੋਂ ਅੱਪਗ੍ਰੇਡ ਉਦੋਂ ਤੱਕ ਕੁਝ ਨਹੀਂ ਬਦਲਦੇ ਜਦੋਂ ਤੱਕ ਕੋਈ ਪ੍ਰਬੰਧਕ ਕੋਈ ਵਿਸ਼ੇਸ਼ਤਾ ਚਾਲੂ ਨਹੀਂ ਕਰਦਾ।';
$string['pedagogy:mastery'] = 'ਡਿਫ਼ਾਲਟ ਤੌਰ \'ਤੇ ਮੁਹਾਰਤ ਟਰੈਕਿੰਗ ਚਾਲੂ';
$string['pedagogy:mastery_desc'] = 'ਚਾਲੂ ਹੋਣ \'ਤੇ, ਹਰ ਕੋਰਸ ਮੁਹਾਰਤ ਟਰੈਕਿੰਗ ਵਿਰਾਸਤ ਵਿੱਚ ਲੈਂਦਾ ਹੈ, ਜਦੋਂ ਤੱਕ ਕੋਰਸ ਦਾ ਆਪਣਾ ਓਵਰਰਾਈਡ ਨਾ ਹੋਵੇ। ਮੁਹਾਰਤ ਲਈ ਚੁਣੇ ਹੋਏ ਸਿਖਲਾਈ ਉਦੇਸ਼ ਲੋੜੀਂਦੇ ਹਨ — ਉਦੇਸ਼ਾਂ ਤੋਂ ਬਿਨਾਂ ਕੋਰਸ ਸੁਚੱਜੇ ਢੰਗ ਨਾਲ ਪਿੱਛੇ ਹਟ ਜਾਂਦੇ ਹਨ, ਕੋਈ ਗਲਤੀ ਨਹੀਂ ਆਉਂਦੀ।';
