$string['settings:prompt_debug_enabled']      = 'Log assembled system prompt to file';
$string['settings:prompt_debug_enabled_desc'] = 'When on, every chat-turn writes the full assembled system prompt and per-section character counts to <code>moodledata/temp/sola_prompt_debug.log</code> (rolling at ~1MB). Default off. Use to measure prompt size empirically and audit which sections contribute the most tokens. The log contains the system prompt only (no learner input or PII).';
$string['settings:socratic_verbose'] = 'ਵਿਸਤ੍ਰਿਤ ਸੁਕਰਾਤੀ ਮੋਡ ਪ੍ਰੌਂਪਟ';
$string['settings:socratic_verbose_desc'] = 'ਚਾਲੂ ਹੋਣ ਉੱਤੇ, ਸੁਕਰਾਤੀ-ਮੋਡ ਵਾਲੇ ਕੋਰਸਾਂ ਨੂੰ ਉਹ ਪੂਰੀ ~600-ਟੋਕਨ ਕਰੋ/ਨਾ-ਕਰੋ ਹਦਾਇਤ ਮਿਲਦੀ ਹੈ ਜੋ ਅਸਲ ਵਿੱਚ v3.9.30 ਵਿੱਚ ਜੋੜੀ ਗਈ ਸੀ। ਬੰਦ ਹੋਣ ਉੱਤੇ (ਡਿਫ਼ਾਲਟ), ਉਹਨਾਂ ਨੂੰ ਇੱਕ-ਸਤਰੀ ਹਦਾਇਤ ਮਿਲਦੀ ਹੈ ਜਿਸ ਦੀ ਪਾਲਣਾ ਆਧੁਨਿਕ ਹੋਸਟ ਕੀਤੇ ਮਾਡਲ ਭਰੋਸੇਯੋਗ ਢੰਗ ਨਾਲ ਕਰਦੇ ਹਨ ਅਤੇ ਜੋ ਪ੍ਰਤੀ ਵਾਰੀ ~600 ਟੋਕਨ ਬਚਾਉਂਦੀ ਹੈ। ਜੇ ਕੋਈ ਕੋਰਸ ਅਜਿਹੇ ਕਮਜ਼ੋਰ ਸਵੈ-ਹੋਸਟ ਮਾਡਲ ਉੱਤੇ ਚੱਲ ਰਿਹਾ ਹੈ ਜਿਸ ਨੂੰ ਸਪਸ਼ਟ ਢਾਂਚਾ ਚਾਹੀਦਾ ਹੈ ਤਾਂ ਇਸ ਨੂੰ ਚਾਲੂ ਕਰੋ।';
$string['settings:prompt_budget_chars'] = 'ਸਿਸਟਮ ਪ੍ਰੌਂਪਟ ਅੱਖਰ ਬਜਟ';
$string['settings:prompt_budget_chars_desc'] = 'Maximum total size of the assembled system prompt before the user message, in characters. The structured prompt builder organises sections by category (identity, course context, learner state, behaviour, markers, safety) and drops or truncates the lowest-priority sections when the budget is exceeded. Safety guidance is always preserved in full. Default 8,000 characters (~2,000 tokens). Lower values reduce per-turn cost; higher values allow more course content to land in-prompt.';
$string['settings:current_page_content_maxchars'] = 'ਮੌਜੂਦਾ ਪੇਜ ਸਮੱਗਰੀ ਦੀ ਹੱਦ (ਅੱਖਰ)';
$string['settings:current_page_content_maxchars_desc'] = 'ਜਦੋਂ RAG ਬੰਦ ਹੋਵੇ, ਮੌਜੂਦਾ ਪੰਨੇ ਦੇ ਟੈਕਸਟ ਦੇ ਅੱਖਰਾਂ ਦੀ ਵੱਧ ਤੋਂ ਵੱਧ ਗਿਣਤੀ ਜੋ ਸਿਸਟਮ ਪ੍ਰੌਂਪਟ ਵਿੱਚ "Current Page Content" ਭਾਗ ਵਜੋਂ ਸ਼ਾਮਲ ਕੀਤੀ ਜਾਂਦੀ ਹੈ। ਡਿਫੌਲਟ 8,000 ਪੰਨਾ-ਵਿਸ਼ੇਸ਼ ਪ੍ਰਸ਼ਨਾਂ ਨੂੰ ਚੰਗੀ ਤਰ੍ਹਾਂ ਆਧਾਰ ਦਿੰਦਾ ਹੈ ਅਤੇ ਨਾਲ ਹੀ ਢਾਂਚੇ ਅਤੇ ਹਦਾਇਤਾਂ ਲਈ ਬਜਟ ਛੱਡਦਾ ਹੈ। (RAG ਯੋਗ ਹੋਣ \'ਤੇ ਪੰਨਾ ਇਸ ਦੀ ਬਜਾਏ ਆਪਣੇ ਸਭ ਤੋਂ ਸੰਬੰਧਤ ਟੁਕੜਿਆਂ ਦੁਆਰਾ ਆਧਾਰਿਤ ਹੁੰਦਾ ਹੈ, ਮੌਜੂਦਾ ਪੰਨੇ ਵੱਲ ਝੁਕਾਅ ਨਾਲ, ਇਸ ਲਈ ਇਹ ਹੱਦ ਲਾਗੂ ਨਹੀਂ ਹੁੰਦੀ।) ਬਹੁਤ ਲੰਬੇ ਪੰਨੇ ਨੂੰ ਸ਼ੁਰੂ ਤੋਂ ਇੰਨੇ ਅੱਖਰਾਂ ਤੱਕ ਕੱਟ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ, ਇਸ ਲਈ ਬਹੁਤ ਲੰਬੇ ਪੰਨੇ ਦਾ ਅੰਤ ਹਵਾਲੇ ਵਜੋਂ ਨਹੀਂ ਦਿੱਤਾ ਜਾ ਸਕਦਾ; RAG ਯੋਗ ਕਰਨ ਨਾਲ ਇਹ ਟਲ ਜਾਂਦਾ ਹੈ। ਲਾਗਤ-ਸਚੇਤ ਸਾਈਟਾਂ ਇਸ ਨੂੰ ਘੱਟ ਸੀਮਤ ਕਰ ਸਕਦੀਆਂ ਹਨ (ਜਿਵੇਂ 3,000-4,000)। 500-8,000 ਰੇਂਜ ਤੱਕ ਸੀਮਤ। <code>prompt_budget_chars</code> ਤੋਂ ਸੁਤੰਤਰ: ਇਹ ਸਿਰਫ਼ ਪੰਨਾ ਭਾਗ ਨੂੰ ਸੀਮਤ ਕਰਦਾ ਹੈ; ਬਜਟ ਪੂਰੇ ਪ੍ਰੌਂਪਟ ਨੂੰ ਸੀਮਤ ਕਰਦਾ ਹੈ।';
$string['settings:prompt_verbosity'] = 'ਪ੍ਰੌਂਪਟ ਵਿਸਤਾਰ';
$string['settings:prompt_verbosity_desc'] = 'ਹਦਾਇਤ ਬਲਾਕਾਂ (ਸੁਕਰਾਤੀ ਮੋਡ, ਬਾਹਰੀ ਸਰੋਤ) ਲਈ ਡਿਫ਼ਾਲਟ ਵਿਸਤਾਰ। ਸੰਖੇਪ (ਡਿਫ਼ਾਲਟ) ਉਹ ਹੈ ਜਿਸ ਦੀ ਪਾਲਣਾ ਆਧੁਨਿਕ ਹੋਸਟ ਕੀਤੇ ਮਾਡਲ ਭਰੋਸੇਯੋਗ ਢੰਗ ਨਾਲ ਕਰਦੇ ਹਨ; ਮਿਆਰੀ ਦਰਮਿਆਨੇ ਦਰਜੇ ਦੇ ਮਾਡਲਾਂ ਲਈ ਸਪਸ਼ਟ ਢਾਂਚਾ ਜੋੜਦਾ ਹੈ; ਵਿਸਤ੍ਰਿਤ ਕਮਜ਼ੋਰ ਸਵੈ-ਹੋਸਟ ਕੀਤੇ ਮਾਡਲਾਂ ਲਈ v3.9.30-ਯੁੱਗ ਦੀ ਭਾਰੀ ਹਦਾਇਤ ਕਾਇਮ ਰੱਖਦਾ ਹੈ। <code>prompt_verbosity_course_&lt;id&gt;</code> ਰਾਹੀਂ ਪ੍ਰਤੀ-ਕੋਰਸ ਓਵਰਰਾਈਡ ਉਪਲਬਧ ਹੈ।';
$string['settings:prompt_verbosity_concise'] = 'ਸੰਖੇਪ (ਹੋਸਟ ਕੀਤੇ ਮਾਡਲਾਂ ਲਈ ਸਿਫ਼ਾਰਸ਼ੀ)';
$string['settings:prompt_verbosity_standard'] = 'ਮਿਆਰੀ';
$string['settings:prompt_verbosity_verbose'] = 'ਵਿਸਤ੍ਰਿਤ (ਕਮਜ਼ੋਰ ਸਵੈ-ਹੋਸਟ ਕੀਤੇ ਮਾਡਲਾਂ ਲਈ)';
$string['settings:prompt_metrics_enabled'] = 'ਪ੍ਰਤੀ-ਸੈਕਸ਼ਨ ਪ੍ਰੌਂਪਟ ਮਾਪ ਇਕੱਠੇ ਕਰੋ';
$string['settings:prompt_metrics_enabled_desc'] = 'ਚਾਲੂ ਹੋਣ ਉੱਤੇ (ਡਿਫ਼ਾਲਟ), ਹਰ ਚੈਟ ਵਾਰੀ ਹਰ ਬਣਾਏ ਗਏ ਪ੍ਰੌਂਪਟ ਲਈ ਇੱਕ JSON ਲਾਈਨ <code>moodledata/sola_prompt_metrics/YYYY-MM-DD.log</code> ਵਿੱਚ ਲਿਖਦੀ ਹੈ, ਜਿਸ ਵਿੱਚ ਪ੍ਰਤੀ-ਸ਼੍ਰੇਣੀ ਅੱਖਰ ਗਿਣਤੀ ਹੁੰਦੀ ਹੈ। ਪਿਛਲੇ 7 ਦਿਨ ਰੱਖੇ ਜਾਂਦੇ ਹਨ। ਮਾਪ ਪ੍ਰਬੰਧਕ ਪੇਜ ਬਜਟ ਸਿਫ਼ਾਰਸ਼ ਲਈ ਇਹਨਾਂ ਨੂੰ ਇਕੱਠਾ ਕਰਦਾ ਹੈ। ਕੋਈ ਵੀ ਨਿੱਜੀ ਪਛਾਣਯੋਗ ਜਾਣਕਾਰੀ ਦਰਜ ਨਹੀਂ ਕੀਤੀ ਜਾਂਦੀ — ਸਿਰਫ਼ ਸੈਕਸ਼ਨਾਂ ਦੇ ਆਕਾਰ। ਜੇ ਤੁਹਾਡੀ ਸੰਸਥਾ ਕੋਈ ਵੀ ਮਾਪ ਫ਼ਾਈਲ ਨਹੀਂ ਚਾਹੁੰਦੀ ਤਾਂ ਇਸ ਨੂੰ ਬੰਦ ਕਰੋ।';
$string['settings:prompt_budget_auto_tune'] = 'ਸਿਸਟਮ ਪ੍ਰੌਂਪਟ ਬਜਟ ਦੀ ਰੋਜ਼ਾਨਾ ਆਪਣੇ-ਆਪ ਸੁਧਾਈ (ਬੰਦ ਕੀਤਾ ਜਾ ਰਿਹਾ)';
$string['settings:prompt_budget_auto_tune_desc'] = 'ਬੰਦ ਕੀਤਾ ਜਾ ਰਿਹਾ ਹੈ। ਜਦ ਤੱਕ ਉੱਪਰਲਾ ਬਜਟ ਮੋਡ <strong>ਨਿਸ਼ਚਿਤ</strong> ਉੱਤੇ ਸੈੱਟ ਨਾ ਹੋਵੇ, ਇਹ ਕੁਝ ਨਹੀਂ ਕਰਦਾ। ਇੱਕ ਰੋਜ਼ਾਨਾ ਕੰਮ ਕਟਾਈ ਉੱਤੇ ਨਜ਼ਰ ਰੱਖ ਕੇ ਅਤੇ ਹੁਣ ਤੱਕ ਵੇਖੇ ਸਭ ਤੋਂ ਵੱਡੇ ਪ੍ਰੌਂਪਟ ਦੇ ਪਿੱਛੇ ਲੱਗ ਕੇ ਅੱਖਰ ਬਜਟ ਦਾ ਅੰਦਾਜ਼ਾ ਲਾਉਂਦਾ ਸੀ। ਮਾਡਲ ਦੀ ਸੰਦਰਭ ਵਿੰਡੋ ਤੋਂ ਬਜਟ ਕੱਢਣਾ ਇਹ ਕੰਮ ਬਿਹਤਰ ਕਰਦਾ ਹੈ: ਇਹ ਡੋਲਦਾ ਨਹੀਂ ਅਤੇ ਇਸ ਨੂੰ ਸ਼ੁਰੂਆਤੀ ਡਾਟਾ ਨਹੀਂ ਚਾਹੀਦਾ। ਦੋਵਾਂ ਵਿੱਚ ਟਕਰਾਅ ਵੀ ਸੀ, ਕਿਉਂਕਿ ਇਹ ਕੰਮ ਅੱਖਰ ਬਜਟ ਲਿਖਦਾ ਹੈ ਅਤੇ ਮੂਲ ਤੋਂ ਵੱਖਰਾ ਕੋਈ ਵੀ ਮੁੱਲ ਕੱਢੇ ਹੋਏ ਬਜਟ ਨੂੰ ਬੰਦ ਕਰ ਦਿੰਦਾ ਹੈ। ਇਸ ਨੂੰ ਬੰਦ ਹੀ ਰਹਿਣ ਦਿਓ; ਆਉਣ ਵਾਲੀ ਰਿਲੀਜ਼ ਵਿੱਚ ਹਟਾ ਦਿੱਤਾ ਜਾਵੇਗਾ। ਸਿਫ਼ਾਰਸ਼ ਹਾਲੇ ਵੀ <a href="/local/ai_course_assistant/prompt_metrics.php">ਪ੍ਰੌਂਪਟ ਮੈਟ੍ਰਿਕਸ</a> ਸਫ਼ੇ ਉੱਤੇ ਦਿਸਦੀ ਹੈ।';
