$string['milestone:streak_subject'] = '{$a->coursename} ਵਿੱਚ {$a->days} ਦਿਨ ਦੀ ਲਗਾਤਾਰ ਲੜੀ';
$string['milestone:streak_body_text'] = "ਸਤਿ ਸ੍ਰੀ ਅਕਾਲ {\$a->firstname},\n\nਤੁਸੀਂ {\$a->coursename} ਵਿੱਚ ਲਗਾਤਾਰ {\$a->days} ਦਿਨ ਹਾਜ਼ਰ ਰਹੇ ਹੋ। ਇਹੋ ਜਿਹੀ ਨਿਰੰਤਰਤਾ ਸਿੱਖਣ ਦਾ ਉਹ ਹਿੱਸਾ ਹੈ ਜਿਸ ਦਾ ਦਿਖਾਵਾ ਕਰਨਾ ਸਭ ਤੋਂ ਔਖਾ ਹੈ।\n\nਜਦੋਂ ਵੀ ਤੁਸੀਂ ਤਿਆਰ ਹੋਵੋ, [[tutorshort]] ਇੱਥੇ ਹੈ।\n\n— {\$a->institution}";
$string['milestone:completion_subject'] = 'ਤੁਸੀਂ {$a->coursename} ਪੂਰਾ ਕਰ ਲਿਆ';
$string['milestone:completion_body_text'] = "ਸਤਿ ਸ੍ਰੀ ਅਕਾਲ {\$a->firstname},\n\nਤੁਸੀਂ {\$a->coursename} ਪੂਰਾ ਕਰ ਲਿਆ। ਇਹ ਇੱਕ ਅਸਲ ਪ੍ਰਾਪਤੀ ਹੈ ਜੋ ਤੁਸੀਂ ਕੀਤੀ ਹੈ।\n\nਜੇ ਤੁਸੀਂ ਅੱਗੇ ਵਧਣਾ ਚਾਹੁੰਦੇ ਹੋ, ਤਾਂ [[tutorshort]] ਤੁਹਾਨੂੰ ਸੰਬੰਧਿਤ ਅਗਲਾ ਕੋਰਸ ਚੁਣਨ ਜਾਂ ਕੋਈ ਦਿਲਚਸਪ ਲੱਗਿਆ ਵਿਸ਼ਾ ਮੁੜ ਵੇਖਣ ਵਿੱਚ ਮਦਦ ਕਰ ਸਕਦਾ ਹੈ।\n\n— {\$a->institution}";
