$string['settings:escalation_intent_patterns_desc'] = 'PCRE, no delimiters. ਪ੍ਰਤੀ ਲਾਈਨ ਇੱਕ ਨਿਯਮਿਤ ਸਮੀਕਰਨ; # ਨਾਲ ਸ਼ੁਰੂ ਹੋਣ ਵਾਲੀਆਂ ਲਾਈਨਾਂ ਨੂੰ ਅਣਡਿੱਠਾ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਸਹਾਇਤਾ ਟਿਕਟ ਤਦ ਹੀ ਖੋਲ੍ਹੀ ਜਾਂਦੀ ਹੈ ਜਦੋਂ ਸਿੱਖਿਆਰਥੀ ਦਾ ਆਪਣਾ ਸੁਨੇਹਾ ਇਹਨਾਂ ਵਿੱਚੋਂ ਕਿਸੇ ਨਾਲ ਮੇਲ ਖਾਂਦਾ ਹੈ, ਤਾਂ ਜੋ ਕੋਰਸ ਸਮੱਗਰੀ ਸਿੱਖਿਆਰਥੀ ਵੱਲੋਂ ਵਧਾਉਣ ਦੀ ਕਾਰਵਾਈ ਨਾ ਕਰਾ ਸਕੇ। ਬਿਲਟ-ਇਨ ਡਿਫੌਲਟ ਵਰਤਣ ਲਈ ਖਾਲੀ ਛੱਡੋ, ਜੋ ਅੰਗਰੇਜ਼ੀ ਦੇ ਨਾਲ ਸਪੇਨੀ, ਫ੍ਰੈਂਚ, ਜਰਮਨ ਅਤੇ ਪੁਰਤਗਾਲੀ ਦੇ ਕੁਝ ਆਮ ਵਾਕਾਂਸ਼ ਸ਼ਾਮਲ ਕਰਦੇ ਹਨ। ਜਿਨ੍ਹਾਂ ਸਾਈਟਾਂ ਦੇ ਸਿੱਖਿਆਰਥੀ ਹੋਰ ਭਾਸ਼ਾ ਵਿੱਚ ਲਿਖਦੇ ਹਨ, ਉਹਨਾਂ ਨੂੰ ਇੱਥੇ ਪੈਟਰਨ ਜੋੜਨੇ ਚਾਹੀਦੇ ਹਨ: ਮੇਲ ਨਾ ਖਾਣ ਵਾਲੇ ਸੁਨੇਹੇ ਦਾ ਮਤਲਬ ਹੈ ਕੋਈ ਟਿਕਟ ਨਹੀਂ ਖੁੱਲ੍ਹੇਗੀ।';
$string['settings:zendesk_require_consent'] = 'ਸਹਾਇਤਾ ਐਸਕੇਲੇਸ਼ਨ ਤੋਂ ਪਹਿਲਾਂ ਸਹਿਮਤੀ ਦੀ ਲੋੜ';
$string['settings:zendesk_require_consent_desc'] = 'ਜਦੋਂ ਚਾਲੂ ਹੋਵੇ (ਸਿਫ਼ਾਰਸ਼ੀ), [[tutorshort]] ਇੱਕ ਗੱਲਬਾਤ ਨੂੰ Zendesk ਸਹਾਇਤਾ ਡੈਸਕ ਨੂੰ ਸਿਰਫ਼ ਤਦ ਐਸਕੇਲੇਟ ਕਰਦਾ ਹੈ ਜਦੋਂ ਸਿੱਖਣ ਵਾਲੇ ਨੇ ਪਹਿਲੀ-ਵਾਰ ਚੱਲਣ ਵਾਲੀ ਸਹਿਮਤੀ ਸੂਚਨਾ ਸਵੀਕਾਰ ਕਰ ਲਈ ਹੋਵੇ, ਜੋ ਦੱਸਦੀ ਹੈ ਕਿ ਮਨੁੱਖੀ ਮਦਦ ਮੰਗਣ ਨਾਲ ਗੱਲਬਾਤ (ਨਾਮ ਅਤੇ ਈਮੇਲ ਸਮੇਤ) ਸਹਾਇਤਾ ਨਾਲ ਸਾਂਝੀ ਹੁੰਦੀ ਹੈ। ਇਸ ਨੂੰ ਸਿਰਫ਼ ਤਦ ਬੰਦ ਕਰੋ ਜੇ ਤੁਸੀਂ ਉਹ ਸਹਿਮਤੀ ਕਿਸੇ ਹੋਰ ਤਰੀਕੇ ਨਾਲ ਪ੍ਰਾਪਤ ਕਰਦੇ ਹੋ; ਇਸ ਦੇ ਬੰਦ ਹੋਣ \'ਤੇ, ਐਸਕੇਲੇਸ਼ਨ ਤੁਰੰਤ ਭੇਜੇ ਜਾਂਦੇ ਹਨ। ਜਦੋਂ ਤੱਕ Zendesk ਐਸਕੇਲੇਸ਼ਨ ਯੋਗ ਨਾ ਹੋਵੇ, ਇਸ ਦਾ ਕੋਈ ਅਸਰ ਨਹੀਂ ਹੁੰਦਾ।';
$string['chat:escalation_needs_consent'] = 'ਜਾਪਦਾ ਹੈ ਕਿ ਇਸ ਲਈ ਸਾਡੀ ਸਹਾਇਤਾ ਟੀਮ ਦੇ ਕਿਸੇ ਮੈਂਬਰ ਦੀ ਲੋੜ ਹੈ। ਇਸ ਨੂੰ ਉਹਨਾਂ ਨੂੰ ਸੌਂਪਣ ਲਈ ਮੈਨੂੰ ਇਹ ਗੱਲਬਾਤ, ਤੁਹਾਡੇ ਨਾਮ ਅਤੇ ਈਮੇਲ ਸਮੇਤ, ਸਹਾਇਤਾ ਡੈਸਕ ਨਾਲ ਸਾਂਝੀ ਕਰਨੀ ਪਵੇਗੀ। ਤੁਸੀਂ ਅਜੇ ਤੱਕ ਇਸ ਲਈ ਸਹਿਮਤ ਨਹੀਂ ਹੋਏ, ਇਸ ਲਈ ਮੈਂ ਕੁਝ ਨਹੀਂ ਭੇਜਿਆ। ਜੇ ਤੁਸੀਂ ਮਨੁੱਖੀ ਮਦਦ ਚਾਹੁੰਦੇ ਹੋ, ਤਾਂ ਕਿਰਪਾ ਕਰਕੇ ਇਸ ਸਹਾਇਕ ਲਈ ਡਾਟਾ-ਸਾਂਝੀਕਰਨ ਸੂਚਨਾ ਸਵੀਕਾਰ ਕਰੋ ਅਤੇ ਦੁਬਾਰਾ ਪੁੱਛੋ, ਜਾਂ ਸਿੱਧਾ ਸਹਾਇਤਾ ਨਾਲ ਸੰਪਰਕ ਕਰੋ।';
$string['privacy:metadata:email_optout'] = 'ਪ੍ਰਤੀ-ਪ੍ਰਾਪਤਕਰਤਾ ਈਮੇਲ ਆਪਟ-ਆਊਟ ਤਰਜੀਹਾਂ (ਪ੍ਰਾਪਤਕਰਤਾ ਨੇ ਕਿਹੜੀਆਂ ਈਮੇਲ ਕਿਸਮਾਂ ਤੋਂ ਗਾਹਕੀ ਰੱਦ ਕੀਤੀ ਹੈ)।';
$string['privacy:metadata:email_optout:email'] = 'ਪ੍ਰਾਪਤਕਰਤਾ ਈਮੇਲ ਪਤਾ ਜਿਸ \'ਤੇ ਆਪਟ-ਆਊਟ ਲਾਗੂ ਹੁੰਦਾ ਹੈ।';
$string['privacy:metadata:email_optout:optout_type'] = 'ਉਹ ਈਮੇਲ ਕਿਸਮ ਜਿਸ ਤੋਂ ਪ੍ਰਾਪਤਕਰਤਾ ਨੇ ਆਪਟ-ਆਊਟ ਕੀਤਾ ਹੈ।';
$string['privacy:metadata:email_optout:userid'] = 'ਉਹ Moodle ਉਪਭੋਗਤਾ ਜਿਸ ਨਾਲ ਆਪਟ-ਆਊਟ ਸੰਬੰਧਿਤ ਹੈ, ਜਦੋਂ ਪਤਾ ਹੋਵੇ।';
$string['chat:consent_scroll_hint'] = 'ਜਾਰੀ ਰੱਖਣ ਤੋਂ ਪਹਿਲਾਂ ਪੂਰਾ ਨੋਟਿਸ ਪੜ੍ਹਨ ਲਈ ਕਿਰਪਾ ਕਰਕੇ ਹੇਠਾਂ ਤੱਕ ਸਕ੍ਰੋਲ ਕਰੋ।';
$string['settings:rag_min_similarity'] = 'ਘੱਟੋ-ਘੱਟ ਸੰਬੰਧਤਾ (ਕੋਸਾਈਨ)';
$string['settings:rag_min_similarity_desc'] = 'ਪ੍ਰਾਪਤ ਕੀਤੇ ਉਹ ਟੁਕੜੇ ਹਟਾਓ ਜਿਨ੍ਹਾਂ ਦੀ ਪ੍ਰਸ਼ਨ ਨਾਲ ਕੋਸਾਈਨ ਸਮਾਨਤਾ ਇਸ ਮੁੱਲ ਤੋਂ ਘੱਟ ਹੈ, ਤਾਂ ਜੋ ਵਿਸ਼ੇ ਤੋਂ ਬਾਹਰਲਾ ਜਾਂ ਘੱਟ ਜਾਣਕਾਰੀ ਵਾਲਾ ਪ੍ਰਸ਼ਨ ਹਮੇਸ਼ਾ ਕਮਜ਼ੋਰ ਮੇਲਾਂ ਨਾਲ Top-K ਤੱਕ ਭਰਨ ਦੀ ਬਜਾਏ ਘੱਟ (ਜਾਂ ਜ਼ੀਰੋ) ਹਵਾਲੇ ਸ਼ਾਮਲ ਕਰੇ। ਰੇਂਜ 0 ਤੋਂ 1; 0 ਇਸ ਗੇਟ ਨੂੰ ਅਯੋਗ ਕਰਦਾ ਹੈ। ਸਹੀ ਮੁੱਲ embedding ਮਾਡਲ \'ਤੇ ਨਿਰਭਰ ਕਰਦਾ ਹੈ: 0.25 text-embedding-3-small ਲਈ ਢੁਕਵਾਂ ਹੈ। ਵਧੇਰੇ ਸਖ਼ਤ ਹੋਣ ਲਈ ਇਸ ਨੂੰ ਵਧਾਓ (ਘੱਟ, ਵਧੇਰੇ ਵਿਸ਼ੇ-ਸੰਬੰਧਤ ਸੰਦਰਭ), ਵਧੇਰੇ ਉਦਾਰ ਹੋਣ ਲਈ ਘਟਾਓ।';
$string['settings:rag_currentpage_boost'] = 'ਮੌਜੂਦਾ ਪੰਨਾ ਬੂਸਟ';
$string['settings:rag_currentpage_boost_desc'] = 'ਉਸ ਪੰਨੇ ਦੇ ਟੁਕੜਿਆਂ ਦੇ ਸੰਬੰਧਤਾ ਸਕੋਰ ਵਿੱਚ ਜੋੜਿਆ ਗਿਆ ਇੱਕ ਛੋਟਾ ਬੋਨਸ ਜੋ ਸਿਖਿਆਰਥੀ ਇਸ ਵੇਲੇ ਦੇਖ ਰਿਹਾ ਹੈ, ਤਾਂ ਜੋ "ਇਸ ਨੂੰ ਸਮਝਾਓ" ਵਰਗੇ ਪ੍ਰਸ਼ਨ ਸਕੋਰ ਨੇੜੇ ਹੋਣ \'ਤੇ ਦਿਸਣ ਵਾਲੇ ਪੰਨੇ ਨੂੰ ਤਰਜੀਹ ਦੇਣ। ਸਿਰਫ਼ ਕ੍ਰਮ: ਇਹ ਕਿਸੇ ਅਪ੍ਰਸੰਗਿਕ ਪੰਨੇ ਦੇ ਟੁਕੜੇ ਨੂੰ ਘੱਟੋ-ਘੱਟ ਸੰਬੰਧਤਾ ਗੇਟ ਤੋਂ ਪਾਰ ਕਰਨ ਲਈ ਮਜਬੂਰ ਨਹੀਂ ਕਰਦਾ। ਅਯੋਗ ਕਰਨ ਲਈ 0 ਸੈੱਟ ਕਰੋ।';
$string['settings:history_mode'] = 'ਇਤਿਹਾਸ ਚੋਣ ਮੋਡ';
$string['settings:history_mode_desc'] = 'ਮਾਡਲ ਨੂੰ ਭੇਜਣ ਤੋਂ ਪਹਿਲਾਂ ਪਿਛਲੀਆਂ ਗੱਲਬਾਤ ਵਾਰੀਆਂ ਕਿਵੇਂ ਚੁਣੀਆਂ ਜਾਂਦੀਆਂ ਹਨ। <strong>ਅਰਥਕ</strong> ਸਿਰਫ਼ ਮੌਜੂਦਾ ਪ੍ਰਸ਼ਨ ਨਾਲ ਸੰਬੰਧਤ ਹਾਲੀਆ ਵਾਰੀਆਂ ਰੱਖਦਾ ਹੈ (ਅਤੇ ਹਮੇਸ਼ਾ ਸਭ ਤੋਂ ਹਾਲੀਆ ਅਦਾਨ-ਪ੍ਰਦਾਨ), ਤਾਂ ਜੋ ਪੁਰਾਣੀ, ਵਿਸ਼ੇ ਤੋਂ ਬਾਹਰਲੀ ਪਹਿਲੀ ਵਾਰੀ ਲਾਗਤ ਨੂੰ ਨਾ ਵਧਾਏ ਜਾਂ ਜਵਾਬ ਨੂੰ ਰਾਹ ਤੋਂ ਨਾ ਭਟਕਾਏ; ਇਹ ਪ੍ਰਤੀ ਸੁਨੇਹਾ ਇੱਕ ਵਾਧੂ embedding ਕਾਲ ਕਰਦਾ ਹੈ। <strong>ਨਵੀਨਤਾ</strong> ਸੰਬੰਧਤਾ ਦੀ ਪਰਵਾਹ ਕੀਤੇ ਬਿਨਾਂ ਆਖ਼ਰੀ "Max Conversation History" ਜੋੜੇ ਰੱਖਦਾ ਹੈ (ਲੰਬੇ ਸਮੇਂ ਤੋਂ ਚੱਲਿਆ ਆ ਰਿਹਾ ਵਿਹਾਰ, ਕੋਈ ਵਾਧੂ ਕਾਲ ਨਹੀਂ)। ਜੇ embedding ਉਪਲਬਧ ਨਹੀਂ ਹੈ, ਤਾਂ ਅਰਥਕ ਮੋਡ ਆਪਣੇ-ਆਪ ਨਵੀਨਤਾ \'ਤੇ ਵਾਪਸ ਆ ਜਾਂਦਾ ਹੈ।';
$string['settings:history_mode_semantic'] = 'ਅਰਥਕ (ਸੰਬੰਧਤ ਹਾਲੀਆ ਵਾਰੀਆਂ)';
$string['settings:history_mode_recency'] = 'ਨਵੀਨਤਾ (ਆਖ਼ਰੀ N ਜੋੜੇ)';
$string['settings:history_semantic_minscore'] = 'ਇਤਿਹਾਸ ਸੰਬੰਧਤਾ ਹੇਠਲੀ ਹੱਦ (ਕੋਸਾਈਨ)';
$string['settings:history_semantic_minscore_desc'] = 'ਅਰਥਕ ਇਤਿਹਾਸ ਮੋਡ ਵਿੱਚ, ਇੱਕ ਪਿਛਲੀ ਵਾਰੀ ਸਿਰਫ਼ ਤਾਂ ਹੀ ਰੱਖੀ ਜਾਂਦੀ ਹੈ ਜੇ ਮੌਜੂਦਾ ਪ੍ਰਸ਼ਨ ਨਾਲ ਇਸ ਦੀ ਸਮਾਨਤਾ ਘੱਟੋ-ਘੱਟ ਇਸ ਮੁੱਲ ਜਿੰਨੀ ਹੋਵੇ (ਸਭ ਤੋਂ ਹਾਲੀਆ ਅਦਾਨ-ਪ੍ਰਦਾਨ ਹਮੇਸ਼ਾ ਰੱਖਿਆ ਜਾਂਦਾ ਹੈ)। ਰੇਂਜ 0 ਤੋਂ 1; ਮਾਡਲ-ਨਿਰਭਰ। ਵਧੇਰੇ ਸਖ਼ਤ ਹੋਣ ਲਈ ਵਧਾਓ (ਘੱਟ ਇਤਿਹਾਸ), ਵਧੇਰੇ ਰੱਖਣ ਲਈ ਘਟਾਓ।';
$string['settings:history_candidates'] = 'ਇਤਿਹਾਸ ਉਮੀਦਵਾਰ ਵਿੰਡੋ';
$string['settings:history_candidates_desc'] = 'ਅਰਥਕ ਇਤਿਹਾਸ ਮੋਡ ਵਿੱਚ, ਸਿਰਫ਼ ਇੰਨੇ ਹਾਲੀਆ ਜੋੜਿਆਂ ਨੂੰ ਸੰਬੰਧਤਾ ਲਈ ਸਕੋਰ ਕੀਤਾ ਜਾਂਦਾ ਹੈ (ਇੱਕ ਲਾਗਤ ਸੀਮਾ)। ਇਸ ਵਿੰਡੋ ਤੋਂ ਪੁਰਾਣੇ ਜੋੜੇ ਨਹੀਂ ਭੇਜੇ ਜਾਂਦੇ। ਇਸ ਨੂੰ "Max Conversation History" ਦੇ ਬਰਾਬਰ ਜਾਂ ਇਸ ਤੋਂ ਵੱਧ ਰੱਖੋ।';

// v5.11.0 - v6.2.0 strings (added 2026-06-10).
$string['settings:embed_provider_voyage'] = 'Voyage AI (voyage-3.5 — ਸਿਫ਼ਾਰਸ਼ੀ; +4 MTEB ਬਨਾਮ OpenAI 3-small, 4x ਸੰਦਰਭ, ਬਹੁ-ਭਾਸ਼ਾਈ)';
$string['settings:rerank_heading'] = 'RAG: ਦੋ-ਪੜਾਅ ਮੁੜ-ਪ੍ਰਾਪਤੀ (re-ranking)';
$string['settings:rerank_heading_desc'] = 'ਵਿਕਲਪਿਕ ਦੂਜਾ ਪ੍ਰਾਪਤੀ ਪੜਾਅ: cosine ਸਮਾਨਤਾ ਚੋਟੀ-N ਉਮੀਦਵਾਰ chunks ਚੁਣਦੀ ਹੈ (ਡਿਫਾਲਟ 50), ਫਿਰ cross-encoder re-ranker ਹਰੇਕ (ਪੁੱਛਗਿੱਛ, chunk) ਜੋੜੇ ਨੂੰ ਸਕੋਰ ਕਰਦਾ ਹੈ ਅਤੇ ਸਭ ਤੋਂ ਵਧੀਆ top-K ਪ੍ਰੌਂਪਟ ਵਿੱਚ ਜਾਂਦੇ ਹਨ। ਡਿਫਾਲਟ ਬੰਦ; re-ranker ਗੈਰ-ਸੰਰਚਿਤ ਜਾਂ ਅਸਫਲ ਹੋਣ \'ਤੇ ਇੱਕਲੇ-ਪੜਾਅ cosine \'ਤੇ ਵਾਪਸ ਆਉਂਦਾ ਹੈ।';
$string['settings:rerank_enabled'] = 'ਦੋ-ਪੜਾਅ ਪ੍ਰਾਪਤੀ (Voyage rerank-2.5)';
$string['settings:rerank_enabled_desc'] = 'ਜਦੋਂ ਚਾਲੂ ਹੋਵੇ, RAG ਪ੍ਰਾਪਤੀ ਦੋ-ਪੜਾਅ ਬਣ ਜਾਂਦੀ ਹੈ: cosine ਸਮਾਨਤਾ ਚੋਟੀ-N ਉਮੀਦਵਾਰ (ਡਿਫਾਲਟ 50) ਵਾਪਸ ਕਰਦੀ ਹੈ, ਫਿਰ Voyage rerank-2.5 cross-encoder ਹਰੇਕ ਨੂੰ ਸਕੋਰ ਕਰਦਾ ਹੈ ਅਤੇ top-K ਪ੍ਰੌਂਪਟ ਵਿੱਚ ਜਾਂਦੇ ਹਨ। ਪ੍ਰਕਾਸ਼ਿਤ ਸੁਧਾਰ: +15 Recall@10 ਉੱਦਮ, +39% NDCG BEIR. ~$0.05/MTok ਬਿਲਿੰਗ। ਹੇਠਾਂ <code>rerank_apikey</code> ਚਾਹੀਦਾ ਹੈ; rerank ਅਸਫਲ ਜਾਂ ਗੈਰ-ਸੰਰਚਿਤ ਹੋਣ \'ਤੇ ਇੱਕਲੇ-ਪੜਾਅ cosine \'ਤੇ ਸੁਚੱਜੇ ਢੰਗ ਨਾਲ ਵਾਪਸ ਆਉਂਦਾ ਹੈ।';
