$string['settings:prompt_section_weights_coach_desc'] = 'ਵਿਕਲਪਿਕ JSON ਆਬਜੈਕਟ ਖਾਸ ਤੌਰ \'ਤੇ graded-quiz coach mode ਦੌਰਾਨ (<code>quizmode=coach</code>) ਅਧਾਰ ਭਾਗ ਭਾਰ ਓਵਰਰਾਈਡ ਕਰਦਾ ਹੈ। ਸਧਾਰਨ chat ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕੀਤੇ ਬਿਨਾਂ ਕੁਇਜ਼ਾਂ ਦੌਰਾਨ ਭਾਰੀ <code>current_page</code> ਵੰਡ ਲਈ ਲਾਭਦਾਇਕ। ਅਧਾਰ ਭਾਰ ਲੈਣ ਲਈ ਖਾਲੀ ਛੱਡੋ।';
$string['prompt_debug_view:title'] = 'ਪ੍ਰੌਂਪਟ debug ਲੌਗ ਦਰਸ਼ਕ';
$string['prompt_debug_view:subtitle'] = 'ਪ੍ਰਤੀ-ਵਾਰੀ ਅਸੈਂਬਲ ਸਿਸਟਮ ਪ੍ਰੌਂਪਟ + ਪ੍ਰਤੀ-ਭਾਗ ਵਿਭਾਜਨ + ਗੱਲਬਾਤ ਇਤਿਹਾਸ + ਮੌਜੂਦਾ ਉਪਭੋਗਤਾ ਸੁਨੇਹਾ + ਅਟੈਚਮੈਂਟ ਮੈਟਾਡੇਟਾ, ਬਿਲਕੁਲ ਉਸੇ ਤਰ੍ਹਾਂ ਜਿਵੇਂ ਮਾਡਲ ਨੂੰ ਮਿਲੇ। ਇਸਦੀ ਵਰਤੋਂ ਇਹ ਜਾਂਚਨ ਲਈ ਕਰੋ ਕਿ ਕੀ ਕੋਈ ਭਾਗ ਜਿਵੇਂ ਮੌਜੂਦਾ ਪੰਨਾ ਸਮੱਗਰੀ ਅਸਲ ਵਿੱਚ ਪ੍ਰੌਂਪਟ ਵਿੱਚ ਆਈ ਅਤੇ ਸਰਵਰ \'ਤੇ SSH ਕੀਤੇ ਬਿਨਾਂ ਜਵਾਬ-ਗੁਣਵੱਤਾ ਸਮੱਸਿਆਵਾਂ ਡੀਬੱਗ ਕਰਨ ਲਈ।';
$string['prompt_debug_view:disabled'] = 'ਪ੍ਰੌਂਪਟ debug ਲੌਗਿੰਗ ਇਸ ਸਮੇਂ ਬੰਦ ਹੈ। ਚਾਲੂ ਹੋਣ ਤੱਕ ਕੋਈ ਨਵੀਂ ਐਂਟਰੀ ਨਹੀਂ ਲਿਖੀ ਜਾਵੇਗੀ।';
$string['prompt_debug_view:enable_link'] = 'ਪਲੱਗਇਨ ਸੈਟਿੰਗਾਂ ਖੋਲ੍ਹੋ "ਅਸੈਂਬਲ ਸਿਸਟਮ ਪ੍ਰੌਂਪਟ ਨੂੰ ਫਾਈਲ ਵਿੱਚ ਲੌਗ ਕਰੋ" ਚਾਲੂ ਕਰਨ ਲਈ।';
$string['prompt_debug_view:no_log_yet'] = 'ਅਜੇ ਕੋਈ ਲੌਗ ਫਾਈਲ ਨਹੀਂ। debug ਲੌਗ ਚਾਲੂ ਕਰਨ ਤੋਂ ਬਾਅਦ ਘੱਟੋ-ਘੱਟ ਇੱਕ chat ਵਾਰੀ ਭੇਜੋ; ਫਾਈਲ ਪਹਿਲੀ ਵਾਰੀ ਲਿਖਣ \'ਤੇ ਬਣਾਈ ਜਾਂਦੀ ਹੈ।';
$string['prompt_debug_view:empty'] = 'ਲੌਗ ਫਾਈਲ ਮੌਜੂਦ ਹੈ ਪਰ ਖਾਲੀ ਹੈ। ਇੱਕ chat ਵਾਰੀ ਭੇਜੋ ਅਤੇ ਤਾਜ਼ਾ ਕਰੋ।';
$string['prompt_debug_view:file_status'] = 'ਲੌਗ ਫਾਈਲ ਆਕਾਰ';
$string['prompt_debug_view:showing'] = 'ਤਾਜ਼ੀਆਂ ਐਂਟਰੀਆਂ ਦਿਖਾ ਰਿਹਾ ਹੈ (ਨਵੀਂ ਪਹਿਲਾਂ), ਸੀਮਾ';
$string['prompt_debug_view:total'] = 'ਕੁੱਲ ਪ੍ਰੌਂਪਟ';
$string['prompt_debug_view:budget'] = 'ਕੈਪਚਰ ਸਮੇਂ ਬਜਟ';
$string['prompt_debug_view:sections'] = 'ਭਾਗ (ਸ਼੍ਰੇਣੀ ਅਨੁਸਾਰ)';
$string['prompt_debug_view:assembled_prompt'] = 'ਅਸੈਂਬਲ ਸਿਸਟਮ ਪ੍ਰੌਂਪਟ';
$string['prompt_debug_view:history'] = 'ਮਾਡਲ ਨੂੰ ਭੇਜਿਆ ਗੱਲਬਾਤ ਇਤਿਹਾਸ';
$string['prompt_debug_view:current_message'] = 'ਮੌਜੂਦਾ ਉਪਭੋਗਤਾ ਸੁਨੇਹਾ';
$string['prompt_debug_view:attachment'] = 'ਅਟੈਚਮੈਂਟ ਮੈਟਾਡੇਟਾ';
$string['prompt_debug_view:show_more'] = 'ਹੋਰ ਐਂਟਰੀਆਂ ਦਿਖਾਓ';
$string['settings:mastery_classifier_provider'] = 'Classifier ਪ੍ਰਦਾਤਾ';
$string['settings:mastery_classifier_provider_desc'] = 'ਪ੍ਰਤੀ-ਵਾਰੀ mastery classifier ਲਈ ਵਰਤਿਆ ਜਾਣ ਵਾਲਾ ਪ੍ਰਦਾਤਾ id। ਡਿਫਾਲਟ AI ਪ੍ਰਦਾਤਾ ਲੈਣ ਲਈ ਖਾਲੀ ਛੱਡੋ। ਡਿਫਾਲਟ <code>openai</code> ਹੇਠਾਂ <code>gpt-4o-mini</code> classifier ਮਾਡਲ ਨਾਲ ਜੋੜਿਆ ਜਾਂਦਾ ਹੈ — structured-output classification ਲਈ ਸਭ ਤੋਂ ਸਸਤਾ TIER 1 ਵਿਕਲਪ (~$220/ਮਹੀਨਾ ਬਚਤ 100k MAU \'ਤੇ)। ਸੈੱਟ ਹੋਣ \'ਤੇ, ਇਸ ਪ੍ਰਦਾਤਾ id ਵਾਲੀ ਤੁਲਨਾ ਪ੍ਰਦਾਤਾਵਾਂ ਵਿੱਚ ਕਤਾਰ API key, base URL, ਅਤੇ temperature ਪ੍ਰਦਾਨ ਕਰਦੀ ਹੈ।';
$string['settings:premium_escalation_heading'] = 'ਪ੍ਰੀਮੀਅਮ escalation ਪੱਧਰ (A.10)';
$string['settings:premium_escalation_heading_desc'] = 'ਪ੍ਰਤੀ-ਵਾਰੀ ਪ੍ਰੀਮੀਅਮ ਮਾਡਲ (ਡਿਫਾਲਟ ਤੌਰ \'ਤੇ Claude Opus 4.8) \'ਤੇ routing ਜਿੱਥੇ workhorse chat ਪੱਧਰ ਸੰਘਰਸ਼ ਕਰਦਾ ਹੈ — ਆਮ ਤੌਰ \'ਤੇ ਬਹੁ-ਕਦਮ ਗਣਿਤ, CS, ਅਤੇ ਵਿਗਿਆਨ ਤਰਕ। 2026-06-09 A.10 bake-off: Opus 4.8 ਨੇ 14.97/15 \'ਤੇ ਜਿੱਤਿਆ ਬਨਾਮ gpt-4o ਦਾ 12.68/15 ਔਖੇ ਪ੍ਰੌਂਪਟਾਂ \'ਤੇ। ਡਿਫਾਲਟ ਬੰਦ। ~5% escalation \'ਤੇ, 100k [[unishort]] MAU \'ਤੇ ਅਧਾਰ chat ਖਰਚ ਤੋਂ ਉੱਪਰ ~$700/ਮਹੀਨਾ ਅਨੁਮਾਨਿਤ।';
$string['settings:premium_escalation_enabled'] = 'ਪ੍ਰੀਮੀਅਮ escalation routing ਚਾਲੂ ਕਰੋ';
$string['settings:premium_escalation_enabled_desc'] = 'ਚਾਲੂ ਹੋਣ \'ਤੇ, ਪ੍ਰਤੀ-ਵਾਰੀ router ਹਰੇਕ chat ਕਾਲ ਲਈ trigger regex ਸੂਚੀ ਅਤੇ ਕੋਰਸ allowlist ਜਾਂਚਦਾ ਹੈ; ਮੇਲ ਖਾਂਦੀਆਂ ਵਾਰੀਆਂ ਪ੍ਰੀਮੀਅਮ ਪ੍ਰਦਾਤਾ ਵੱਲ route ਕੀਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ। ਪ੍ਰੀਮੀਅਮ ਕਤਾਰ ਗਾਇਬ ਜਾਂ instantiate ਕਰਨ ਵਿੱਚ ਅਸਫਲ ਹੋਣ \'ਤੇ workhorse ਪ੍ਰਦਾਤਾ \'ਤੇ ਵਾਪਸ ਆਉਂਦਾ ਹੈ।';
$string['settings:premium_escalation_provider'] = 'ਪ੍ਰੀਮੀਅਮ ਪ੍ਰਦਾਤਾ';
$string['settings:premium_escalation_provider_desc'] = 'ਪ੍ਰੀਮੀਅਮ ਕਾਲਾਂ route ਕਰਨ ਲਈ ਪ੍ਰਦਾਤਾ id। ਤੁਲਨਾ ਪ੍ਰਦਾਤਾਵਾਂ ਵਿੱਚ ਕਤਾਰ ਨਾਲ ਮੇਲ ਖਾਣਾ ਚਾਹੀਦਾ ਹੈ। ਡਿਫਾਲਟ <code>claude</code>।';
$string['settings:premium_escalation_model'] = 'ਪ੍ਰੀਮੀਅਮ model';
$string['settings:premium_escalation_model_desc'] = 'ਪ੍ਰੀਮੀਅਮ ਪ੍ਰਦਾਤਾ ਨੂੰ ਭੇਜਿਆ ਮਾਡਲ ਨਾਮ। A.10 bake-off ਫੈਸਲੇ ਅਨੁਸਾਰ ਡਿਫਾਲਟ <code>claude-sonnet-5</code>।';
$string['settings:premium_escalation_triggers'] = 'ਪ੍ਰੀਮੀਅਮ trigger regexes';
$string['settings:premium_escalation_triggers_desc'] = 'ਇੱਕ PCRE regex ਪ੍ਰਤੀ ਲਾਈਨ (delimiter ਤੋਂ ਬਿਨਾਂ; case-insensitive ਮੇਲ ਆਟੋਮੈਟਿਕ ਲਾਗੂ ਹੁੰਦਾ ਹੈ)। # ਨਾਲ ਸ਼ੁਰੂ ਹੋਣ ਵਾਲੀਆਂ ਲਾਈਨਾਂ ਟਿੱਪਣੀਆਂ ਹਨ। A.10 bake-off ਤੋਂ ਕਿਉਰੇਟਡ ਡਿਫਾਲਟ ਸੈੱਟ ਵਰਤਣ ਲਈ ਖਾਲੀ ਛੱਡੋ (ਬਹੁ-ਕਦਮ STEM markers: "derive", "prove that", "step by step", LaTeX math, fenced code blocks, big-O, ਇੰਟੀਗ੍ਰਲ, optimization, ਆਦਿ)।';
$string['settings:premium_escalation_course_tags'] = 'ਪ੍ਰੀਮੀਅਮ ਕੋਰਸ allowlist';
$string['settings:premium_escalation_course_tags_desc'] = 'ਇੱਕ ਕੋਰਸ shortname ਜਾਂ idnumber prefix ਪ੍ਰਤੀ ਲਾਈਨ। ਮੇਲ ਖਾਂਦੇ ਕੋਰਸ ਵਿੱਚ ਹਰੇਕ ਵਾਰੀ ਸੁਨੇਹਾ regex ਤੋਂ ਨਿਰਵਿਘਨ ਆਟੋ-escalate ਹੁੰਦੀ ਹੈ। ਮੇਲ case-insensitive prefix ਹੈ — "MATH" MATH121, MATH205, ਆਦਿ ਨਾਲ ਮੇਲ ਖਾਂਦਾ ਹੈ।';
$string['settings:spend_cap_per_course_default'] = 'ਡਿਫਾਲਟ ਪ੍ਰਤੀ-ਕੋਰਸ ਖਰਚ ਸੀਮਾ (USD)';
$string['settings:spend_cap_per_course_default_desc'] = 'ਰੱਖਿਆਤਮਕ ਸੀਮਾ ਹਰੇਕ ਕੋਰਸ \'ਤੇ ਲਾਗੂ ਜਿਸਦੀ ਆਪਣੀ ਪ੍ਰਤੀ-ਕੋਰਸ ਖਰਚ ਸੀਮਾ ਸੰਰਚਿਤ ਨਹੀਂ ਹੈ। ਵਿਅਕਤੀਗਤ ਕੋਰਸਾਂ ਨੂੰ ਟਿਊਨ ਕੀਤੇ ਬਿਨਾਂ ਕਿਸੇ ਵੀ ਇੱਕ ਕੋਰਸ ਦਾ ਮਾਸਿਕ ਖਰਚ $30 \'ਤੇ ਸੀਮਿਤ ਕਰਨ ਲਈ ਉਦਾਹਰਨ ਵਜੋਂ <code>30</code> ਸੈੱਟ ਕਰੋ। <code>0</code> = ਕੋਈ ਡਿਫਾਲਟ ਨਹੀਂ। ਜਦੋਂ ਕੋਈ ਕੋਰਸ ਇਸ ਸੀਮਾ ਦਾ 80% / 95% / 100% ਪਾਰ ਕਰਦਾ ਹੈ, ਮੌਜੂਦਾ spend-guard ਚੇਤਾਵਨੀ ਪਾਈਪਲਾਈਨ ਐਡਮਿਨ ਨੂੰ ਸੂਚਨਾ ਭੇਜਦੀ ਹੈ।';
$string['settings:cost_anomaly_heading'] = 'ਲਾਗਤ ਅਸੰਗਤਤਾ ਖੋਜਕਰਤਾ (v6.0)';
$string['settings:cost_anomaly_heading_desc'] = 'ਰੋਜ਼ਾਨਾ ਅਨੁਸੂਚਿਤ ਕੰਮ (<code>cost_anomaly_check</code>) ਜੋ ਅੱਜ ਦੇ ਸਾਈਟ-ਵਿਆਪੀ [[tutorshort]] ਖਰਚ ਦੀ ਤੁਲਨਾ rolling 7-ਦਿਨ ਮੱਧਮਾਨ ਨਾਲ ਕਰਦਾ ਹੈ। ਜਦੋਂ ਅੱਜ configured multiplier × median ਤੋਂ ਵੱਧ ਜਾਵੇ ਤਾਂ <code>spend_notify_emails</code> ਸੂਚੀ ਨੂੰ ਈਮੇਲ ਕਰਦਾ ਹੈ। ਮੌਜੂਦਾ 80% / 95% / 100% ਖਰਚ-ਸੀਮਾ ਥ੍ਰੈਸ਼ਹੋਲਡਾਂ ਤੋਂ ਖੁੰਝੇ ਤਿੰਨ ਅਸਫਲਤਾ ਮੋਡਾਂ ਨੂੰ ਫੜਦਾ ਹੈ। ਡਿਫਾਲਟ ਬੰਦ।';
$string['settings:cost_anomaly_enabled'] = 'ਲਾਗਤ ਅਸੰਗਤਤਾ ਖੋਜਕਰਤਾ ਚਾਲੂ ਕਰੋ';
$string['settings:cost_anomaly_enabled_desc'] = 'ਚਾਲੂ ਹੋਣ \'ਤੇ, ਰੋਜ਼ਾਨਾ ਅਨੁਸੂਚਿਤ ਕੰਮ ਅੱਜ ਦੇ ਖਰਚ ਦੀ rolling 7-ਦਿਨ ਮੱਧਮਾਨ ਨਾਲ ਤੁਲਨਾ ਕਰਦਾ ਹੈ ਅਤੇ ਅਸੰਗਤਤਾ \'ਤੇ ਪ੍ਰਸ਼ਾਸਕਾਂ ਨੂੰ ਈਮੇਲ ਕਰਦਾ ਹੈ। ਚਾਲੂ ਕਰਨ ਤੋਂ ਬਾਅਦ ਪਹਿਲੇ 7 ਦਿਨ <code>insufficient_history</code> ਸਥਿਤੀ ਦਿਖਾਉਂਦੇ ਹਨ ਅਤੇ ਕਦੇ ਚੇਤਾਵਨੀ ਨਹੀਂ ਭੇਜਦੇ। ਪ੍ਰਤੀ-ਦਿਨ idempotent।';
$string['settings:cost_anomaly_multiplier'] = 'ਅਸੰਗਤਤਾ multiplier';
$string['settings:cost_anomaly_multiplier_desc'] = 'ਚੇਤਾਵਨੀ trigger ਕਰਨ ਲਈ ਅੱਜ ਦਾ ਖਰਚ ਇਸ multiplier × 7-ਦਿਨ ਮੱਧਮਾਨ ਤੋਂ ਵੱਧ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ। ਡਿਫਾਲਟ <code>2.0</code>। ਪਹਿਲਾਂ ਚੇਤਾਵਨੀ ਲਈ <code>1.5</code> ਤੱਕ ਘਟਾਓ। ਜੇ [[unishort]] ਦੀ ਵਰਤੋਂ 2x spikes ਨੂੰ ਆਮ ਬਣਾ ਦਿੰਦੀ ਹੈ ਤਾਂ <code>3.0</code> ਤੱਕ ਵਧਾਓ।';
$string['task:cost_anomaly_check'] = '[[tutorshort]] ਲਾਗਤ ਅਸੰਗਤਤਾ ਜਾਂਚ (ਰੋਜ਼ਾਨਾ)';

// v6.4.0 signed policy bundle strings (added 2026-06-11).
$string['settings:policy_bundle_heading'] = 'ਦਸਤਖਤ ਕੀਤਾ ਨੀਤੀ ਬੰਡਲ (ਰਿਮੋਟ ਵਿਹਾਰ ਅਪਡੇਟ)';
$string['settings:policy_bundle_heading_desc'] = 'ਕੋਡ ਡਿਪਲੋਏ ਕੀਤੇ ਬਿਨਾਂ ਕ੍ਰਿਪਟੋਗ੍ਰਾਫਿਕ ਤੌਰ ਤੇ ਦਸਤਖਤ ਕੀਤੇ JSON ਫਾਈਲ ਤੋਂ ਵਿਹਾਰ ਸੈਟਿੰਗਾਂ (ਪ੍ਰੌਂਪਟ, ਰਾਊਟਿੰਗ, ਐਸਕਲੇਸ਼ਨ ਟ੍ਰਿਗਰ, RAG ਟਿਊਨਿੰਗ, ਖਰਚ ਨੀਤੀ) ਲਾਗੂ ਕਰੋ। ਇੱਕ ਰੋਜ਼ਾਨਾ ਅਨੁਸੂਚਿਤ ਕੰਮ ਬੰਡਲ URL ਲਿਆਉਂਦਾ ਹੈ, ਹੇਠਾਂ ਦਿੱਤੀ ਜਨਤਕ ਕੁੰਜੀ ਦੇ ਵਿਰੁੱਧ Ed25519 ਦਸਤਖਤ ਦੀ ਤਸਦੀਕ ਕਰਦਾ ਹੈ, ਅਤੇ ਸੈਟਿੰਗਾਂ ਤਾਂ ਹੀ ਲਾਗੂ ਕਰਦਾ ਹੈ ਜੇ ਹਰ ਕੁੰਜੀ ਬਿਲਟ-ਇਨ ਅਨੁਮਤੀ ਸੂਚੀ ਵਿੱਚ ਹੋਵੇ ਅਤੇ ਬੰਡਲ ਸੰਸਕਰਣ ਆਖਰੀ ਲਾਗੂ ਕੀਤੇ ਨਾਲੋਂ ਨਵਾਂ ਹੋਵੇ। API ਕੁੰਜੀਆਂ, URL, webhooks ਅਤੇ ਸੁਰੱਖਿਆ ਸੈਟਿੰਗਾਂ ਕਦੇ ਵੀ ਬੰਡਲ ਦੁਆਰਾ ਸੈੱਟ ਨਹੀਂ ਕੀਤੀਆਂ ਜਾ ਸਕਦੀਆਂ। <code>admin/cli/policy_bundle_tool.php</code> (keygen, sign, verify, status, sync) ਨਾਲ ਬੰਡਲ ਬਣਾਓ ਅਤੇ ਦਸਤਖਤ ਕਰੋ।';
$string['settings:policy_bundle_enabled'] = 'ਨੀਤੀ ਬੰਡਲ ਸਿੰਕ ਯੋਗ ਬਣਾਓ';
$string['settings:policy_bundle_enabled_desc'] = 'ਯੋਗ ਹੋਣ ਤੇ, ਰੋਜ਼ਾਨਾ ਕੰਮ ਦਸਤਖਤ ਕੀਤੇ ਬੰਡਲ ਲਿਆਉਂਦਾ ਅਤੇ ਲਾਗੂ ਕਰਦਾ ਹੈ। ਮੂਲ ਰੂਪ ਵਿੱਚ ਬੰਦ। ਅਯੋਗ ਕਰਨ ਨਾਲ ਸਾਰੇ ਸਿੰਕ ਤੁਰੰਤ ਰੁਕ ਜਾਂਦੇ ਹਨ; ਪਹਿਲਾਂ ਤੋਂ ਲਾਗੂ ਸੈਟਿੰਗਾਂ ਆਪਣੇ ਮੁੱਲ ਬਣਾਈ ਰੱਖਦੀਆਂ ਹਨ।';
$string['settings:policy_bundle_url'] = 'ਨੀਤੀ ਬੰਡਲ URL';
$string['settings:policy_bundle_url_desc'] = 'ਦਸਤਖਤ ਕੀਤੇ ਬੰਡਲ JSON ਦਾ HTTPS URL (ਉਦਾਹਰਨ ਲਈ S3 ਆਬਜੈਕਟ ਜਾਂ GitHub raw URL)। URL AI ਪ੍ਰਦਾਤਾ ਐਂਡਪੋਆਇੰਟਾਂ ਵਾਂਗੂ SSRF ਵੈਲੀਡੇਸ਼ਨ ਤੋਂ ਲੰਘਦਾ ਹੈ; ਨਿੱਜੀ ਨੈੱਟਵਰਕ ਜਾਂ plain-http ਹੋਸਟਾਂ ਨੂੰ SSRF ਭਰੋਸੇਯੋਗ ਐਂਡਪੋਆਇੰਟ ਅਨੁਮਤੀ ਸੂਚੀ ਵਿੱਚ ਐਂਟਰੀ ਦੀ ਲੋੜ ਹੈ।';
$string['settings:policy_bundle_pubkey'] = 'ਨੀਤੀ ਬੰਡਲ ਜਨਤਕ ਕੁੰਜੀ';
$string['settings:policy_bundle_pubkey_desc'] = 'ਬੰਡਲ ਦਸਤਖਤਾਂ ਦੀ ਤਸਦੀਕ ਕਰਨ ਲਈ ਵਰਤੀ ਜਾਂਦੀ Base64 Ed25519 ਜਨਤਕ ਕੁੰਜੀ। <code>policy_bundle_tool.php --keygen</code> ਨਾਲ ਕੀਪੇਅਰ ਬਣਾਓ; ਨਿੱਜੀ ਕੁੰਜੀ ਬੰਡਲ ਲੇਖਕ ਕੋਲ ਰਹਿੰਦੀ ਹੈ ਅਤੇ ਕਦੇ ਵੀ ਕਿਤੇ ਅਪਲੋਡ ਨਹੀਂ ਕੀਤੀ ਜਾਣੀ ਚਾਹੀਦੀ।';
$string['settings:policy_bundle_status'] = 'ਆਖਰੀ ਸਿੰਕ';
$string['settings:policy_bundle_applied_version'] = 'ਲਾਗੂ ਸੰਸਕਰਣ';
$string['task:policy_bundle_sync'] = '[[tutorshort]] ਦਸਤਖਤ ਕੀਤਾ ਨੀਤੀ ਬੰਡਲ ਸਿੰਕ';
$string['policy_bundle:invalid'] = 'ਨੀਤੀ ਬੰਡਲ ਰੱਦ: {$a}';
$string['prompt_debug_view:retrieved_chunks'] = 'ਪ੍ਰਾਪਤ ਕੀਤੇ ਟੁਕੜੇ (RAG ਚੋਣ)';
$string['prompt_debug_view:retrieved_chunks_hint'] = 'ਇਸ ਸਵਾਲ ਲਈ ਰੀਟ੍ਰੀਵਰ ਵੱਲੋਂ ਚੁਣੇ ਗਏ ਹਵਾਲੇ, ਉਨ੍ਹਾਂ ਦੇ ਸੰਬੰਧਤਾ ਸਕੋਰ ਅਤੇ ਸਰੋਤ (cmid) ਸਮੇਤ ਦਰਜਾਬੰਦੀ ਕ੍ਰਮ ਵਿੱਚ। ਇਹ ਪੁਸ਼ਟੀ ਕਰਨ ਲਈ ਇਸ ਦੀ ਵਰਤੋਂ ਕਰੋ ਕਿ ਮਾਡਲ ਨੂੰ ਸਭ ਤੋਂ ਵੱਧ ਮੇਲ ਖਾਂਦੀ ਕੋਰਸ ਸਮੱਗਰੀ ਮਿਲੀ।';
$string['settings:avatar_animation_enabled'] = 'ਅਵਤਾਰ ਐਨੀਮੇਸ਼ਨ';
$string['settings:avatar_animation_enabled_desc'] = 'ਤਿਆਰ ਕੀਤੇ SVG ਅਵਤਾਰ ਨੂੰ ਐਨੀਮੇਟ ਕਰੋ: ਅਕਿਰਿਆਸ਼ੀਲ ਹੋਣ ਵੇਲੇ ਅੱਖ ਝਪਕਾਉਣਾ, ਅਤੇ ਸਹਾਇਕ ਦੇ ਬੋਲਣ ਵੇਲੇ ਟੈਕਸਟ-ਟੂ-ਸਪੀਚ ਆਡੀਓ ਨਾਲ ਸਮਕਾਲੀ ਮੂੰਹ ਦੀ ਹਰਕਤ। ਸਿੱਖਿਆਰਥੀ ਦੇ ਡਿਵਾਈਸ ਦੀ ਘੱਟੀਆਂ ਹਰਕਤ ਦੀ ਤਰਜੀਹ ਦਾ ਸਤਿਕਾਰ ਕਰਦਾ ਹੈ। A/B ਮਾਪ ਲਈ ਪ੍ਰਤੀ-ਕੋਰਸ ਓਵਰਰਾਈਡ: config ਮੁੱਲ avatar_animation_course_COURSEID ਨੂੰ 0 ਜਾਂ 1 \'ਤੇ ਸੈੱਟ ਕਰੋ।';
$string['analytics:exp_heading'] = 'A/B ਪ੍ਰਯੋਗ ਤੁਲਨਾ';
$string['analytics:exp_desc'] = 'ਚੁਣੇ ਗਏ ਸਮੇਂ ਦੀ ਰੇਂਜ ਵਿੱਚ ਦੋ ਕੋਰਸਾਂ ਵਿਚਕਾਰ ਸ਼ਮੂਲੀਅਤ ਦੀ ਤੁਲਨਾ ਕਰੋ। ਪ੍ਰਤੀ-ਕੋਰਸ ਪ੍ਰਯੋਗਾਂ ਲਈ ਬਣਾਇਆ ਗਿਆ (ਉਦਾਹਰਨ ਵਜੋਂ ਅਵਤਾਰ ਐਨੀਮੇਸ਼ਨ ਜਾਂਚ): ਇੱਕ ਕੋਰਸ ਵਿੱਚ ਓਵਰਰਾਈਡ ਰੱਖੋ, ਦੂਜੇ ਨੂੰ ਕੰਟਰੋਲ ਵਜੋਂ ਛੱਡੋ, ਅਤੇ ਇੱਥੇ ਅੰਤਰ ਪੜ੍ਹੋ।';
