$string['analytics:exp_active_users'] = 'ਸਰਗਰਮ [[tutorshort]] ਉਪਭੋਗਤਾ';
$string['analytics:exp_usage_rate'] = 'ਵਰਤੋਂ ਦਰ (%)';
$string['analytics:exp_sessions'] = 'ਸੈਸ਼ਨ';
$string['analytics:exp_messages'] = 'ਸੁਨੇਹੇ';
