$string['settings:redash_allowed_origin'] = 'Redash ਲਈ ਮਨਜ਼ੂਰ ਮੂਲ (CORS)';
$string['settings:redash_allowed_origin_desc'] = 'ਖਾਲੀ ਛੱਡੋ (ਸਿਫਾਰਸ਼ ਕੀਤਾ): ਨਿਰਯਾਤ ਨੂੰ Redash ਦੁਆਰਾ ਸਰਵਰ-ਤੋਂ-ਸਰਵਰ ਪ੍ਰਾਪਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ ਅਤੇ ਇਸ ਨੂੰ ਕਿਸੇ ਬ੍ਰਾਊਜ਼ਰ CORS ਹੈੱਡਰ ਦੀ ਲੋੜ ਨਹੀਂ ਹੁੰਦੀ। ਸਿਰਫ਼ ਤਾਂ ਹੀ ਇੱਕ ਸਟੀਕ ਮੂਲ ਸੈੱਟ ਕਰੋ (ਉਦਾਹਰਨ ਲਈ https://redash.example.org) ਜਦੋਂ ਕਿਸੇ ਬ੍ਰਾਊਜ਼ਰ-ਅਧਾਰਿਤ ਡੈਸ਼ਬੋਰਡ ਨੂੰ ਨਿਰਯਾਤ ਸਿੱਧਾ ਪੜ੍ਹਨਾ ਪਵੇ। ਕਦੇ ਵੀ ਵਾਈਲਡਕਾਰਡ ਦੀ ਵਰਤੋਂ ਨਾ ਕਰੋ।';

// Soapbox speech practice (v6.7.0).
$string['privacy:metadata:local_ai_course_assistant_practice_scores:session_meta'] = 'ਸੈਸ਼ਨ ਲਈ ਤੁਹਾਡੇ ਵੱਲੋਂ ਦਿੱਤਾ ਗਿਆ ਚੋਣਵਾਂ ਮੈਟਾਡਾਟਾ, ਜਿਵੇਂ ਕਿ Soapbox ਭਾਸ਼ਣ ਦਾ ਨਾਮ, ਵਿਸ਼ਾ ਅਤੇ ਟੀਚਾ ਲੰਬਾਈ। ਇਸ ਵਿੱਚ ਕਦੇ ਵੀ ਆਡੀਓ ਜਾਂ ਟ੍ਰਾਂਸਕ੍ਰਿਪਟ ਸ਼ਾਮਲ ਨਹੀਂ ਹੁੰਦਾ।';
$string['pedagogy:soapbox'] = 'Soapbox ਭਾਸ਼ਣ ਫੀਡਬੈਕ ਮੂਲ ਰੂਪ ਵਿੱਚ ਚਾਲੂ';
$string['pedagogy:soapbox_desc'] = 'ਜਦੋਂ ਚਾਲੂ ਹੋਵੇ, ਤਾਂ Soapbox ਭਾਸ਼ਣ-ਅਭਿਆਸ ਟੂਲ ਹਰ ਕੋਰਸ ਵਿੱਚ ਉਪਲਬਧ ਹੁੰਦਾ ਹੈ ਜਦੋਂ ਤੱਕ ਕੋਰਸ ਦਾ ਆਪਣਾ ਓਵਰਰਾਈਡ ਨਾ ਹੋਵੇ। ਬੰਦ ਰੱਖੋ ਅਤੇ ਇਸਨੂੰ ਸਿਰਫ਼ ਉਹਨਾਂ ਕੋਰਸਾਂ ਵਿੱਚ ਚਾਲੂ ਕਰੋ ਜਿੰਨ੍ਹਾਂ ਨੂੰ ਇਸਦੀ ਲੋੜ ਹੈ (ਆਮ ਤੌਰ ਤੇ ਭਾਸ਼ਣ ਅਤੇ ਸੰਚਾਰ ਕੋਰਸ)।';
$string['settings:soapbox_stt_mode'] = 'Soapbox ਟ੍ਰਾਂਸਕ੍ਰਿਪਸ਼ਨ ਮੋਡ';
$string['settings:soapbox_stt_mode_desc'] = 'Soapbox ਇੱਕ ਰਿਕਾਰਡ ਕੀਤੇ ਭਾਸ਼ਣ ਨੂੰ ਟੈਕਸਟ ਵਿੱਚ ਕਿਵੇਂ ਬਦਲਦਾ ਹੈ। ਸਰਵਰ ਸੰਰਚਿਤ Whisper ਪ੍ਰਦਾਤਾ ਵਰਤਦਾ ਹੈ (ਸਵੈ-ਹੋਸਟ ਮੁਫ਼ਤ ਹੈ; ਹੋਸਟ ਕੀਤਾ OpenAI ਲਗਭਗ USD 0.006 ਪ੍ਰਤੀ ਮਿੰਟ ਹੈ)। ਬ੍ਰਾਊਜ਼ਰ ਸਿੱਖਣ ਵਾਲੇ ਦੀ ਬਿਲਟ-ਇਨ ਭਾਸ਼ਣ ਪਛਾਣ ਵਰਤਦਾ ਹੈ (ਮੁਫ਼ਤ, ਕੋਈ ਸਰਵਰ ਨਹੀਂ, ਸਿਰਫ਼ Chrome ਅਤੇ Safari ਵਿੱਚ ਕੰਮ ਕਰਦਾ ਹੈ)। ਸਰਵਰ ਦੀ ਸਿਫਾਰਸ਼ ਕੀਤੀ ਜਾਂਦੀ ਹੈ ਤਾਂ ਜੋ ਟ੍ਰਾਂਸਕ੍ਰਿਪਸ਼ਨ ਦੀ ਗੁਣਵੱਤਾ ਸਿੱਖਣ ਵਾਲੇ ਦੇ ਬ੍ਰਾਊਜ਼ਰ ਉੱਤੇ ਨਿਰਭਰ ਨਾ ਕਰੇ।';
$string['settings:soapbox_stt_mode_server'] = 'ਸਰਵਰ (Whisper ਪ੍ਰਦਾਤਾ)';
$string['settings:soapbox_stt_mode_browser'] = 'ਬ੍ਰਾਊਜ਼ਰ (ਮੁਫ਼ਤ, ਕੋਈ ਸਰਵਰ ਨਹੀਂ)';
$string['soapbox:title'] = 'Soapbox';
$string['soapbox:link'] = 'Soapbox ਭਾਸ਼ਣ ਅਭਿਆਸ';
$string['soapbox:disabled'] = 'ਇਸ ਕੋਰਸ ਲਈ Soapbox ਯੋਗ ਨਹੀਂ ਹੈ।';
$string['soapbox:intro'] = 'ਭਾਸ਼ਣ ਦਿਓ ਅਤੇ ਕੋਚਿੰਗ ਪ੍ਰਾਪਤ ਕਰੋ। ਚੋਣਵੇਂ ਤੌਰ ਤੇ ਨਾਮ, ਵਿਸ਼ਾ ਅਤੇ ਟੀਚਾ ਲੰਬਾਈ ਸੈੱਟ ਕਰੋ, ਫਿਰ ਆਪਣੇ ਆਪ ਨੂੰ ਬੋਲਦੇ ਹੋਏ ਰਿਕਾਰਡ ਕਰੋ। Soapbox ਤੁਹਾਡੇ ਭਾਸ਼ਣ ਨੂੰ ਟ੍ਰਾਂਸਕ੍ਰਾਈਬ ਕਰਦਾ ਹੈ, ਇਸਨੂੰ ਬੋਲਣ ਦੇ ਰੁਬਰਿਕ ਅਨੁਸਾਰ ਅੰਕ ਦਿੰਦਾ ਹੈ, ਅਤੇ ਤੁਹਾਨੂੰ ਠੋਸ ਸੁਝਾਅ ਦਿੰਦਾ ਹੈ। ਤੁਹਾਡਾ ਆਡੀਓ ਅਤੇ ਟ੍ਰਾਂਸਕ੍ਰਿਪਟ ਕਦੇ ਵੀ ਸਟੋਰ ਨਹੀਂ ਕੀਤੇ ਜਾਂਦੇ, ਸਿਰਫ਼ ਤੁਹਾਡੇ ਅੰਕ ਅਤੇ ਫੀਡਬੈਕ।';
$string['soapbox:optional'] = 'ਚੋਣਵਾਂ';
$string['soapbox:name_label'] = 'ਇਸ ਭਾਸ਼ਣ ਨੂੰ ਨਾਮ ਦਿਓ';
$string['soapbox:topic_label'] = 'ਵਿਸ਼ਾ';
$string['soapbox:time_label'] = 'ਟੀਚਾ ਲੰਬਾਈ';
$string['soapbox:no_target'] = 'ਕੋਈ ਟੀਚਾ ਨਹੀਂ';
$string['soapbox:record'] = 'ਭਾਸ਼ਣ ਰਿਕਾਰਡ ਕਰੋ';
$string['soapbox:stop'] = 'ਰੋਕੋ';
$string['soapbox:recording'] = 'ਰਿਕਾਰਡ ਹੋ ਰਿਹਾ ਹੈ। ਕੁਦਰਤੀ ਤੌਰ ਤੇ ਬੋਲੋ; ਜਦੋਂ ਤੁਸੀਂ ਪੂਰਾ ਕਰ ਲਵੋ ਤਾਂ ਰੋਕੋ ਉੱਤੇ ਕਲਿੱਕ ਕਰੋ।';
$string['soapbox:transcribing'] = 'ਤੁਹਾਡੇ ਭਾਸ਼ਣ ਨੂੰ ਟ੍ਰਾਂਸਕ੍ਰਾਈਬ ਕੀਤਾ ਜਾ ਰਿਹਾ ਹੈ…';
$string['soapbox:scoring'] = 'ਤੁਹਾਡੇ ਭਾਸ਼ਣ ਦੇ ਅੰਕ ਦਿੱਤੇ ਜਾ ਰਹੇ ਹਨ…';
$string['soapbox:too_short'] = 'ਉਹ ਰਿਕਾਰਡਿੰਗ ਅੰਕ ਦੇਣ ਲਈ ਬਹੁਤ ਛੋਟੀ ਸੀ। ਘੱਟੋ-ਘੱਟ ਇੱਕ ਜਾਂ ਦੋ ਵਾਕਾਂ ਦਾ ਟੀਚਾ ਰੱਖੋ ਅਤੇ ਮੁੜ ਕੋਸ਼ਿਸ਼ ਕਰੋ।';
$string['soapbox:mic_denied'] = 'ਰਿਕਾਰਡ ਕਰਨ ਲਈ ਮਾਈਕ੍ਰੋਫੋਨ ਪਹੁੰਚ ਦੀ ਲੋੜ ਹੈ। ਮਾਈਕ੍ਰੋਫੋਨ ਪਹੁੰਚ ਦੀ ਆਗਿਆ ਦਿਓ ਅਤੇ ਮੁੜ ਕੋਸ਼ਿਸ਼ ਕਰੋ।';
