$string['radar_report:privacy_note'] = 'ਇਸ ਰਿਪੋਰਟ ਵਿੱਚ ਸਾਰਾ ਸਿੱਖਿਆਰਥੀ ਡਾਟਾ ਗੁਮਨਾਮ ਕੀਤਾ ਗਿਆ ਹੈ। ਇਸਨੂੰ ਜਨਤਕ ਤੌਰ ਤੇ ਸਾਂਝਾ ਨਾ ਕਰੋ।';

$string['settings:hidden_categories'] = 'ਲੁਕਾਈਆਂ ਕੋਰਸ ਸ਼੍ਰੇਣੀਆਂ';
$string['settings:hidden_categories_desc'] = 'ਕਾਮਿਆਂ ਨਾਲ ਵੱਖ ਕੀਤੀ ਕੋਰਸ ਸ਼੍ਰੇਣੀਆਂ ਦੇ ਨਾਵਾਂ ਜਾਂ ਆਈਡੀਆਂ ਦੀ ਸੂਚੀ, ਜਿੱਥੇ ਸਹਾਇਕ ਨਹੀਂ ਦਿਖਣਾ ਚਾਹੀਦਾ। ਉਦਾਹਰਨ: "ਕੋਰਸ ਵਿਕਾਸ, 42"। ਸੰਪਾਦਨ ਮੋਡ ਚਾਲੂ ਹੋਣ ਤੇ ਵੀ ਸਹਾਇਕ ਆਪਣੇ ਆਪ ਲੁਕ ਜਾਂਦਾ ਹੈ।';
$string['settings:provider_heading'] = 'ਏਆਈ ਪ੍ਰਦਾਤਾ ਅਤੇ ਗੱਲਬਾਤ';
$string['settings:provider_heading_desc'] = 'ਏਆਈ ਪਲੇਟਫਾਰਮ, ਮਾਡਲ ਅਤੇ ਗੱਲਬਾਤ ਦੇ ਵਿਹਾਰ ਨੂੰ ਸੰਰਚਿਤ ਕਰੋ।';
$string['settings:claude_temperature_allow_prefixes'] = 'temperature ਪੈਰਾਮੀਟਰ ਦਾ ਸਮਰਥਨ ਕਰਨ ਵਾਲੇ Claude ਮਾਡਲ';
$string['settings:claude_temperature_allow_prefixes_desc'] = 'ਹਰ ਲਾਈਨ ਵਿੱਚ ਇੱਕ ਮਾਡਲ ਨਾਮ ਦਾ ਅਗੇਤਰ। ਜਿਨ੍ਹਾਂ Anthropic ਮਾਡਲਾਂ ਦਾ ਨਾਮ ਇਹਨਾਂ ਵਿੱਚੋਂ ਕਿਸੇ ਨਾਲ ਸ਼ੁਰੂ ਹੁੰਦਾ ਹੈ, ਉਹ ਅਜੇ ਵੀ <code>temperature</code> ਸੈਂਪਲਿੰਗ ਪੈਰਾਮੀਟਰ ਸਵੀਕਾਰ ਕਰਦੇ ਹਨ। ਜਿਹੜਾ Claude ਮਾਡਲ ਕਿਸੇ ਅਗੇਤਰ ਨਾਲ ਮੇਲ ਨਹੀਂ ਖਾਂਦਾ, ਉਸ ਲਈ temperature ਛੱਡ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ (Opus 4.7 ਤੋਂ ਬਾਅਦ ਦੇ ਤਰਕ ਮਾਡਲ ਇਸਨੂੰ HTTP 400 ਗਲਤੀ ਨਾਲ ਰੱਦ ਕਰਦੇ ਹਨ)। ਪਲੱਗਇਨ ਨਾਲ ਆਏ ਮੂਲ ਮੁੱਲ ਲਈ ਖਾਲੀ ਛੱਡੋ।';
$string['settings:max_tokens'] = 'ਵੱਧ ਤੋਂ ਵੱਧ ਜਵਾਬ ਦੀ ਲੰਬਾਈ (ਟੋਕਨ)';
$string['settings:max_tokens_desc'] = 'ਏਆਈ ਦੇ ਹਰ ਜਵਾਬ ਲਈ ਵੱਧ ਤੋਂ ਵੱਧ ਟੋਕਨ ਗਿਣਤੀ। ਘੱਟ ਮੁੱਲ ਛੋਟੇ ਅਤੇ ਤੇਜ਼ ਜਵਾਬ ਦਿੰਦੇ ਹਨ। 512 = ਲਗਭਗ 2-3 ਵਾਕ, 1024 = ਲਗਭਗ 1-2 ਪੈਰੇ, 2048 = ਲੰਬੀਆਂ ਵਿਆਖਿਆਵਾਂ। ਕੋਈ ਹੱਦ ਨਾ ਰੱਖਣ ਲਈ 0 ਸੈੱਟ ਕਰੋ (ਪ੍ਰਦਾਤਾ ਦਾ ਮੂਲ ਮੁੱਲ ਲਾਗੂ ਹੋਵੇਗਾ)।';
$string['settings:profile_update_interval'] = 'ਸਿੱਖਿਆਰਥੀ ਪ੍ਰੋਫਾਈਲ ਅੱਪਡੇਟ ਅੰਤਰਾਲ';
$string['settings:profile_update_interval_desc'] = 'ਕਿਸੇ ਕੋਰਸ ਵਿੱਚ ਸਿੱਖਿਆਰਥੀ ਦੇ ਇੰਨੇ ਸੁਨੇਹਿਆਂ ਤੋਂ ਬਾਅਦ ਸਹਾਇਕ ਇੱਕ ਸਿੱਖਣ ਪ੍ਰੋਫਾਈਲ ਬਣਾਉਂਦਾ (ਜਾਂ ਤਾਜ਼ਾ ਕਰਦਾ) ਹੈ ਜੋ ਤਾਕਤਾਂ, ਕਮਜ਼ੋਰੀਆਂ, ਸਿੱਖਣ ਦੀ ਸ਼ੈਲੀ ਅਤੇ ਦਿਲਚਸਪੀਆਂ ਦਾ ਸਾਰ ਦਿੰਦਾ ਹੈ। ਵਿਅਕਤੀਗਤ ਜਵਾਬਾਂ ਲਈ ਇਹ ਪ੍ਰੋਫਾਈਲ ਸਿਸਟਮ ਪ੍ਰੌਂਪਟ ਵਿੱਚ ਸ਼ਾਮਲ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਬੰਦ ਕਰਨ ਲਈ 0 ਸੈੱਟ ਕਰੋ। ਮੂਲ: 10।';
$string['settings:enable_thinking'] = 'ਵਿਸਤ੍ਰਿਤ ਤਰਕ (ਸਿਰਫ਼ Claude)';
$string['settings:enable_thinking_desc'] = 'Claude ਮਾਡਲਾਂ ਲਈ ਅਨੁਕੂਲ ਤਰਕ ਚਾਲੂ ਕਰਦਾ ਹੈ। ਜਵਾਬ ਦੇਣ ਤੋਂ ਪਹਿਲਾਂ ਕਿਸੇ ਸਮੱਸਿਆ ਬਾਰੇ ਕਦੋਂ ਅਤੇ ਕਿੰਨਾ ਸੋਚਣਾ ਹੈ, ਇਹ Claude ਖੁਦ ਤੈਅ ਕਰਦਾ ਹੈ। ਗੁੰਝਲਦਾਰ ਸਵਾਲਾਂ ਵਿੱਚ ਸ਼ੁੱਧਤਾ ਵਧਾਉਂਦਾ ਹੈ, ਪਰ ਟੋਕਨ ਵਰਤੋਂ ਅਤੇ ਦੇਰੀ ਵਧਾਉਂਦਾ ਹੈ। ਤਰਕ ਦੀ ਸਮੱਗਰੀ ਸਿੱਖਿਆਰਥੀਆਂ ਨੂੰ ਨਹੀਂ ਦਿਖਾਈ ਜਾਂਦੀ। ਹੋਰ ਪ੍ਰਦਾਤਾ ਇਸ ਸੈਟਿੰਗ ਨੂੰ ਅਣਦੇਖਾ ਕਰਦੇ ਹਨ।';
$string['settings:rag_sources_heading'] = 'RAG ਸਮੱਗਰੀ ਸਰੋਤ';
$string['settings:rag_sources_heading_desc'] = 'ਚੁਣੋ ਕਿ RAG ਇੰਡੈਕਸਰ ਕਿਹੜੀਆਂ ਕਿਸਮਾਂ ਦੀ ਕੋਰਸ ਸਮੱਗਰੀ ਵਿੱਚੋਂ ਲਿਖਤ ਕੱਢੇ। <a href="{$a}">RAG ਪ੍ਰਸ਼ਾਸਨ ਪੰਨੇ</a> ਦੇ ਸਥਿਤੀ ਸੂਚਕ ਦਿਖਾਉਂਦੇ ਹਨ ਕਿ ਹਰ ਐਕਸਟਰੈਕਟਰ ਕੋਲ ਕੰਮ ਕਰਨ ਲਈ ਲੋੜੀਂਦਾ ਸਭ ਕੁਝ ਹੈ ਜਾਂ ਨਹੀਂ (ਜਿਵੇਂ pdftotext ਟੂਲ ਜਾਂ Cloudflare ਮਨਜ਼ੂਰੀ ਸੂਚੀ)।';
$string['settings:rag_extract_pdf'] = 'PDF ਫਾਈਲਾਂ ਇੰਡੈਕਸ ਕਰੋ (mod_resource)';
$string['settings:rag_extract_pdf_desc'] = '<code>pdftotext</code> (poppler) ਟੂਲ ਰਾਹੀਂ ਅੱਪਲੋਡ ਕੀਤੀਆਂ PDF ਫਾਈਲਾਂ ਵਿੱਚੋਂ ਲਿਖਤ ਕੱਢਦਾ ਹੈ। ਟੂਲ ਦਾ ਰਾਹ ਆਪਣੇ ਆਪ ਲੱਭਿਆ ਜਾਂਦਾ ਹੈ; ਲੋੜ ਹੋਵੇ ਤਾਂ ਹੇਠਾਂ ਦੱਸੋ।';
$string['settings:rag_pdftotext_path'] = 'pdftotext ਟੂਲ ਦਾ ਰਾਹ';
$string['settings:rag_pdftotext_path_desc'] = 'ਆਪਣੇ ਆਪ ਲੱਭਣ ਲਈ ਖਾਲੀ ਛੱਡੋ (<code>/usr/bin/pdftotext</code>, <code>/usr/local/bin/pdftotext</code> ਅਤੇ <code>which pdftotext</code> ਜਾਂਚੇ ਜਾਂਦੇ ਹਨ)। ਸਿਰਫ਼ ਤਾਂ ਭਰੋ ਜੇ ਤੁਹਾਡੀ ਇੰਸਟਾਲੇਸ਼ਨ ਕਿਤੇ ਹੋਰ ਹੈ।';
$string['settings:rag_extract_docx'] = 'DOCX ਫਾਈਲਾਂ ਇੰਡੈਕਸ ਕਰੋ (mod_resource)';
$string['settings:rag_extract_docx_desc'] = 'PHP ਦੇ ZipArchive ਰਾਹੀਂ ਅੱਪਲੋਡ ਕੀਤੇ Word ਦਸਤਾਵੇਜ਼ਾਂ ਵਿੱਚੋਂ ਲਿਖਤ ਕੱਢਦਾ ਹੈ। ਕੋਈ ਬਾਹਰੀ ਨਿਰਭਰਤਾ ਨਹੀਂ ਚਾਹੀਦੀ।';
$string['settings:rag_extract_pptx'] = 'PPTX ਫਾਈਲਾਂ ਇੰਡੈਕਸ ਕਰੋ (mod_resource)';
$string['settings:rag_extract_pptx_desc'] = 'PHP ਦੇ ZipArchive ਰਾਹੀਂ ਅੱਪਲੋਡ ਕੀਤੀਆਂ ਆਧੁਨਿਕ PowerPoint ਪੇਸ਼ਕਾਰੀਆਂ ਵਿੱਚੋਂ ਲਿਖਤ ਕੱਢਦਾ ਹੈ। ਸਲਾਈਡਾਂ ਦੇ ਕ੍ਰਮ ਅਨੁਸਾਰ ਸਲਾਈਡ ਅਤੇ ਬੁਲਾਰੇ ਦੇ ਨੋਟਾਂ ਦਾ XML ਘੁੰਮਦਾ ਹੈ; ਕੋਈ ਬਾਹਰੀ ਨਿਰਭਰਤਾ ਨਹੀਂ ਚਾਹੀਦੀ। ਪੁਰਾਣੀਆਂ ਬਾਈਨਰੀ <code>.ppt</code> ਫਾਈਲਾਂ ਸਮਰਥਿਤ ਨਹੀਂ ਹਨ — ਉਹ ਪੇਸ਼ਕਾਰੀਆਂ <code>.pptx</code> ਵਜੋਂ ਦੁਬਾਰਾ ਸੰਭਾਲੋ।';
$string['settings:rag_extract_h5p'] = 'H5P ਸਮੱਗਰੀ ਇੰਡੈਕਸ ਕਰੋ (mod_h5p)';
$string['settings:rag_extract_h5p_desc'] = 'H5P ਸਮੱਗਰੀ ਦਾ JSON ਘੁੰਮਦਾ ਹੈ ਅਤੇ ਲਿਖਤ ਵਾਲੇ ਸਾਰੇ ਖੇਤਰ ਇੰਡੈਕਸ ਕਰਦਾ ਹੈ (ਸਵਾਲ, ਜਵਾਬ, ਫੀਡਬੈਕ, ਵੇਰਵੇ)। H5P ਸਮੱਗਰੀ ਕਿਸਮਾਂ ਦਾ ਮੈਟਾਡੇਟਾ ਵਿਸ਼ਾਲ ਹੈ; ਹੱਦੀ ਮਾਮਲਿਆਂ ਵਿੱਚ ਕੁਝ ਗਲਤ ਮੇਲ ਹੋ ਸਕਦੇ ਹਨ।';
$string['settings:rag_extract_scorm'] = 'SCORM ਪੈਕੇਜ ਇੰਡੈਕਸ ਕਰੋ (mod_scorm)';
$string['settings:rag_extract_scorm_desc'] = 'SCORM ਪੈਕੇਜ ਖੋਲ੍ਹ ਕੇ <code>imsmanifest.xml</code>, ਸਾਰੀਆਂ <code>.html</code> ਫਾਈਲਾਂ ਅਤੇ Articulate Storyline ਸਮੱਗਰੀ ਸਤਰਾਂ ਇੰਡੈਕਸ ਕਰਦਾ ਹੈ। SCORM ਪ੍ਰਕਿਰਿਆ ਮਹਿੰਗੀ ਹੋ ਸਕਦੀ ਹੈ, ਇਸ ਲਈ <strong>ਮੂਲ ਰੂਪ ਵਿੱਚ ਬੰਦ</strong> ਹੈ। ਵੱਧ ਤੋਂ ਵੱਧ ਪੈਕੇਜ ਆਕਾਰ <code>rag_scorm_max_mb</code> ਤੈਅ ਕਰਦਾ ਹੈ।';
$string['settings:rag_scorm_max_mb'] = 'ਇੰਡੈਕਸ ਕਰਨ ਲਈ ਵੱਧ ਤੋਂ ਵੱਧ SCORM ਪੈਕੇਜ ਆਕਾਰ (MB)';
$string['settings:rag_scorm_max_mb_desc'] = 'ਵਾਧੂ ਮੈਮਰੀ ਵਰਤੋਂ ਤੋਂ ਬਚਣ ਲਈ ਇਸ ਮੁੱਲ ਤੋਂ ਵੱਡੇ SCORM ਪੈਕੇਜ ਛੱਡ ਦਿੰਦਾ ਹੈ।';
$string['settings:rag_fetch_transcripts'] = 'ਸ਼ਾਮਲ ਵੀਡੀਓ ਅਤੇ ਇੰਟਰਐਕਟਿਵ ਸਮੱਗਰੀ ਲਈ ਲਿਖਤੀ ਰੂਪ ਲਿਆਓ';
$string['settings:rag_fetch_transcripts_desc'] = 'ਸ਼ਾਮਲ iframe (Synthesia, YouTube, Articulate, Genially) ਲੱਭਣ ਲਈ mod_page ਅਤੇ mod_book ਦੀ ਸਮੱਗਰੀ ਸਕੈਨ ਕਰਦਾ ਹੈ ਅਤੇ ਹਰ ਸ਼ਾਮਲ ਵਸਤੂ ਨਾਲ ਆਏ ਲਿਖਤੀ ਰੂਪ ਦਾ ਪਤਾ ਲਿਆਉਂਦਾ ਹੈ (ਫਰੇਮ ਦੇ ਉੱਪਰ ਅਤੇ ਹੇਠਾਂ ਦੋਵੇਂ ਪਾਸੇ ਲੱਭਦਾ ਹੈ)। ਇਸ ਸਰਵਰ ਤੋਂ ਲਿਖਤੀ ਰੂਪ ਦੇ ਹੋਸਟ ਤੱਕ ਬਾਹਰ ਜਾਣ ਵਾਲਾ HTTPS ਕਨੈਕਸ਼ਨ ਲੋੜੀਂਦਾ ਹੈ। <strong>ਮੂਲ ਰੂਪ ਵਿੱਚ ਬੰਦ</strong>; ਲਿਖਤੀ ਰੂਪ ਦੇ ਪ੍ਰਦਾਤਾ ਵੱਲੋਂ ਇਸ ਸਰਵਰ ਨੂੰ ਆਪਣੀ ਮਨਜ਼ੂਰੀ ਸੂਚੀ ਵਿੱਚ ਪਾਉਣ ਤੋਂ ਬਾਅਦ ਚਾਲੂ ਕਰੋ (ਜਿਵੇਂ IP ਆਧਾਰਿਤ Cloudflare ਨਿਯਮ ਰਾਹੀਂ)।';
$string['settings:rag_iframe_host_patterns'] = 'iframe ਹੋਸਟ ਪੈਟਰਨ';
$string['settings:rag_iframe_host_patterns_desc'] = 'ਹਰ ਲਾਈਨ ਵਿੱਚ ਇੱਕ ਰੈਗੂਲਰ ਐਕਸਪ੍ਰੈਸ਼ਨ, ਜੋ iframe ਦੇ <code>src</code> ਗੁਣ ਨਾਲ ਮਿਲਾਇਆ ਜਾਂਦਾ ਹੈ। ਮਿਲਦਾ ਹਰ ਫਰੇਮ ਇੱਕ ਇੰਟਰਐਕਟਿਵ ਸ਼ਾਮਲ ਵਸਤੂ ਮੰਨਿਆ ਜਾਂਦਾ ਹੈ ਜਿਸਦਾ ਲਿਖਤੀ ਰੂਪ ਜੋੜ ਕੇ ਇੰਡੈਕਸ ਕਰਨਾ ਹੁੰਦਾ ਹੈ। <code>#</code> ਨਾਲ ਸ਼ੁਰੂ ਹੋਣ ਵਾਲੀਆਂ ਲਾਈਨਾਂ ਟਿੱਪਣੀਆਂ ਹਨ।';
$string['settings:rag_transcript_url_pattern'] = 'ਲਿਖਤੀ ਰੂਪ ਦੇ ਪਤੇ ਦਾ ਪੈਟਰਨ';
$string['settings:rag_transcript_url_pattern_desc'] = 'ਲਿਖਤੀ ਰੂਪ ਦੇ ਲਿੰਕਾਂ ਦੇ ਪਤਿਆਂ ਨਾਲ ਮਿਲਦਾ ਰੈਗੂਲਰ ਐਕਸਪ੍ਰੈਸ਼ਨ। ਲੱਭੇ ਹਰ iframe ਲਈ ਇੰਡੈਕਸਰ ਸਭ ਤੋਂ ਨੇੜਲਾ ਮਿਲਦਾ ਲਿੰਕ (ਉੱਪਰ ਜਾਂ ਹੇਠਾਂ) ਚੁਣ ਕੇ ਦੋਵਾਂ ਨੂੰ ਜੋੜਦਾ ਹੈ। ਲਿਖਤੀ ਰੂਪ ਜੋੜਨਾ ਬੰਦ ਕਰਨ ਲਈ ਖਾਲੀ ਛੱਡੋ।';
$string['settings:performance_heading'] = 'ਕਾਰਗੁਜ਼ਾਰੀ';
$string['settings:performance_heading_desc'] = 'ਏਆਈ ਪ੍ਰੌਂਪਟ ਵਿੱਚ ਕਿੰਨੀ ਕੋਰਸ ਸਮੱਗਰੀ ਸ਼ਾਮਲ ਹੋਵੇ, ਇਹ ਤੈਅ ਕਰਦਾ ਹੈ। ਘੱਟ ਮੁੱਲ ਦਾ ਮਤਲਬ ਤੇਜ਼ ਜਵਾਬ ਪਰ ਏਆਈ ਲਈ ਘੱਟ ਸੰਦਰਭ।';
$string['settings:max_content_per_resource'] = 'ਪ੍ਰਤੀ ਸਰੋਤ ਵੱਧ ਤੋਂ ਵੱਧ ਸਮੱਗਰੀ (ਅੱਖਰ)';
$string['settings:max_content_per_resource_desc'] = 'ਹਰ ਪੰਨੇ ਜਾਂ ਕਿਤਾਬ ਦੇ ਅਧਿਆਇ ਵਿੱਚੋਂ ਕੱਢੇ ਜਾਂਦੇ ਵੱਧ ਤੋਂ ਵੱਧ ਅੱਖਰ। ਘੱਟ ਮੁੱਲ ਪ੍ਰੌਂਪਟ ਦਾ ਆਕਾਰ ਘਟਾਉਂਦੇ ਹਨ ਅਤੇ ਜਵਾਬ ਤੇਜ਼ ਕਰਦੇ ਹਨ।';
$string['settings:max_total_content'] = 'ਵੱਧ ਤੋਂ ਵੱਧ ਕੁੱਲ ਸਮੱਗਰੀ (ਅੱਖਰ)';
$string['settings:max_total_content_desc'] = 'ਸਿਸਟਮ ਪ੍ਰੌਂਪਟ ਵਿੱਚ ਸ਼ਾਮਲ ਕੋਰਸ ਸਮੱਗਰੀ ਦੇ ਵੱਧ ਤੋਂ ਵੱਧ ਕੁੱਲ ਅੱਖਰ। ਘੱਟ ਮੁੱਲ ਪ੍ਰੌਂਪਟ ਦਾ ਆਕਾਰ ਘਟਾਉਂਦੇ ਹਨ ਅਤੇ ਜਵਾਬ ਤੇਜ਼ ਕਰਦੇ ਹਨ।';
$string['settings:spend_guard_heading'] = 'ਖਰਚ ਸੁਰੱਖਿਆ ਅਤੇ ਅਨੁਕੂਲਕ';
$string['settings:spend_guard_heading_desc'] = 'ਹਰ ਮਿਆਦ ਲਈ LLM ਖਰਚ ਦੀਆਂ ਹੱਦਾਂ ਤੈਅ ਕਰੋ। ਹੱਦ ਪੂਰੀ ਹੋਣ ਤੇ [[tutorshort]] ਬੇਨਤੀਆਂ ਰੋਕ ਦਿੰਦਾ ਹੈ ਜਾਂ ਤੁਹਾਡੀ ਬਦਲਵੀਂ ਲੜੀ ਵਿੱਚੋਂ ਸਸਤੇ ਪ੍ਰਦਾਤਾ ਤੇ ਚਲਾ ਜਾਂਦਾ ਹੈ। ਮੌਜੂਦਾ ਖਰਚ ਦੀ ਸਥਿਤੀ ਅਤੇ ਅਨੁਕੂਲਕ ਦੀਆਂ ਸਿਫ਼ਾਰਸ਼ਾਂ ਲਈ <a href="{$a}">ਟੋਕਨ ਲਾਗਤ ਪੰਨਾ</a> ਵੇਖੋ।';
$string['settings:spend_cap_period'] = 'ਖਰਚ ਹੱਦ ਦੀ ਮਿਆਦ';
$string['settings:spend_cap_period_desc'] = 'ਖਰਚ ਦੀ ਹੱਦ ਕਿੰਨੀ ਵਾਰ ਮੁੜ ਸੈੱਟ ਹੋਵੇਗੀ। ਕੈਲੰਡਰ ਅਨੁਸਾਰ: ਮਹੀਨਾਵਾਰ 1 ਤਾਰੀਖ਼ ਨੂੰ, ਹਫ਼ਤਾਵਾਰੀ ਸੋਮਵਾਰ ਨੂੰ ਅਤੇ ਰੋਜ਼ਾਨਾ ਅੱਧੀ ਰਾਤ ਨੂੰ ਸ਼ੁਰੂ ਹੁੰਦੀ ਹੈ।';
$string['settings:spend_cap_site'] = 'ਪੂਰੀ ਸਾਈਟ ਦੀ ਖਰਚ ਹੱਦ (USD)';
$string['settings:spend_cap_site_desc'] = 'ਮੌਜੂਦਾ ਮਿਆਦ ਵਿੱਚ ਸਾਰੇ ਕੋਰਸਾਂ ਅਤੇ ਸਮਰੱਥਾਵਾਂ ਲਈ ਸਾਂਝੀ USD ਹੱਦ। <code>0</code> = ਬੇਹੱਦ। ਹੇਠਾਂ ਦਿੱਤੀਆਂ ਸਮਰੱਥਾ-ਵਾਰ ਹੱਦਾਂ ਸੈੱਟ ਹੋਣ ਤੇ ਉਹਨਾਂ ਨੂੰ ਪਹਿਲ ਮਿਲਦੀ ਹੈ।';
$string['settings:spend_cap_chat'] = 'ਚੈਟ ਦੀ ਹੱਦ (USD)';
$string['settings:spend_cap_chat_desc'] = 'ਸਿਰਫ਼ ਸਿੱਖਿਆਰਥੀ ਚੈਟ ਅਤੇ ਕਵਿਜ਼ਾਂ ਲਈ ਹੱਦ। <code>0</code> = ਪੂਰੀ ਸਾਈਟ ਦੀ ਹੱਦ ਵਰਤੀ ਜਾਂਦੀ ਹੈ।';
$string['settings:spend_cap_voice'] = 'ਆਵਾਜ਼ ਦੀ ਹੱਦ (USD)';
$string['settings:spend_cap_voice_desc'] = 'ਆਵਾਜ਼ ਲਈ ਹੱਦ (Realtime + TTS + STT)। ਆਵਾਜ਼ ਆਮ ਤੌਰ ਤੇ ਸਭ ਤੋਂ ਵੱਡਾ ਖਰਚ ਹੁੰਦੀ ਹੈ — ਇਸਨੂੰ ਪਹਿਲਾਂ ਸੀਮਤ ਕਰੋ।';
$string['settings:spend_cap_rag'] = 'RAG ਦੀ ਹੱਦ (USD)';
$string['settings:spend_cap_rag_desc'] = 'ਕੋਰਸ ਇੰਡੈਕਸ ਕਰਨ ਦੌਰਾਨ ਹੋਣ ਵਾਲੀਆਂ ਏਮਬੈਡਿੰਗ ਕਾਲਾਂ ਲਈ ਹੱਦ।';
$string['settings:spend_cap_analytics'] = 'ਵਿਸ਼ਲੇਸ਼ਣ ਦੀ ਹੱਦ (USD)';
$string['settings:spend_cap_analytics_desc'] = 'ਪ੍ਰਸ਼ਾਸਕ ਦੀਆਂ Learning Radar ਪੁੱਛਗਿੱਛਾਂ ਲਈ ਹੱਦ।';
$string['settings:spend_failover_chain'] = 'ਬਦਲਵੀਂ ਲੜੀ';
$string['settings:spend_failover_chain_desc'] = 'ਹੱਦ ਪੂਰੀ ਹੋਣ ਤੇ [[tutorshort]] ਇਹਨਾਂ ਪ੍ਰਦਾਤਾਵਾਂ ਨੂੰ ਕ੍ਰਮ ਅਨੁਸਾਰ ਅਜ਼ਮਾਉਂਦਾ ਹੈ। ਹਰ ਲਾਈਨ ਵਿੱਚ ਇੱਕ ਇੰਦਰਾਜ, <code>capability:label</code> ਰੂਪ ਵਿੱਚ। ਲੇਬਲ ਤੁਲਨਾ ਪ੍ਰਦਾਤਾਵਾਂ (<code>chat</code> / <code>analytics</code> ਲਈ) ਜਾਂ ਆਵਾਜ਼ ਪ੍ਰਦਾਤਾਵਾਂ (<code>voice</code> ਲਈ) ਦੇ ਇੰਦਰਾਜਾਂ ਵੱਲ ਇਸ਼ਾਰਾ ਕਰਦੇ ਹਨ। <code>#</code> ਨਾਲ ਸ਼ੁਰੂ ਹੋਣ ਵਾਲੀਆਂ ਲਾਈਨਾਂ ਟਿੱਪਣੀਆਂ ਹਨ। ਉਦਾਹਰਨ:<br><code>chat:claude-haiku<br>chat:ollama-local<br>voice:openai-prod<br>analytics:deepseek</code>';
$string['settings:failover_per_call_enabled'] = 'ਹਰ ਕਾਲ ਤੇ ਬਦਲਵੇਂ ਵੱਲ ਜਾਣਾ (v5.5.0)';
$string['settings:failover_per_call_enabled_desc'] = 'ਚਾਲੂ ਹੋਣ ਤੇ ਹਰ ਚੈਟ ਕਾਲ ਮੁੱਖ ਪ੍ਰਦਾਤਾ ਨੂੰ ਬਦਲਵੀਂ ਲੜੀ ਦੇ ਲਪੇਟੇ ਵਿੱਚ ਰੱਖਦੀ ਹੈ। ਜੇ ਕਿਸੇ ਕਾਲ ਵਿੱਚ ਸਮਾਂ ਖਤਮ ਹੋ ਜਾਵੇ ਜਾਂ 5xx ਗਲਤੀ ਆਵੇ, ਤਾਂ [[tutorshort]] ਉੱਪਰਲੀ <strong>ਬਦਲਵੀਂ ਲੜੀ</strong> ਦੇ ਅਗਲੇ ਇੰਦਰਾਜ ਤੇ ਚਲਾ ਜਾਂਦਾ ਹੈ ਅਤੇ ਅਸਫਲ ਪ੍ਰਦਾਤਾ ਲਈ 15 ਮਿੰਟ ਦਾ ਸਰਕਟ ਖੋਲ੍ਹ ਦਿੰਦਾ ਹੈ। ਹਰ ਤਬਦੀਲੀ ਇੱਕ ਆਡਿਟ ਲਾਈਨ ਲਿਖਦੀ ਹੈ (<code>failover_fallthrough</code>); ਚਾਲੂ ਕਰਨ ਤੋਂ ਬਾਅਦ ਲੜੀ ਕੰਮ ਕਰ ਰਹੀ ਹੈ ਜਾਂ ਨਹੀਂ, ਇਸਦੀ ਪੁਸ਼ਟੀ ਲਈ ਪ੍ਰਸ਼ਾਸਨ -> [[tutorshort]] -> ਆਡਿਟ ਲੌਗ ਵੇਖੋ। ਮੂਲ ਰੂਪ ਵਿੱਚ ਬੰਦ; ਲੜੀ ਦੀ ਪੁਸ਼ਟੀ ਹੋਣ ਤੋਂ ਬਾਅਦ ਅਤੇ ਤੁਹਾਡੀ ਸੰਸਥਾ ਵੱਲੋਂ ਲੜੀ ਦੇ ਹਰ ਪ੍ਰਦਾਤਾ ਲਈ ਲੋੜੀਂਦੇ ਡੇਟਾ ਪ੍ਰੋਸੈਸਿੰਗ ਸਮਝੌਤੇ ਹੋਣ ਦੀ ਪੁਸ਼ਟੀ ਤੋਂ ਬਾਅਦ ਹੀ ਚਾਲੂ ਕਰੋ।';
$string['settings:failover_timeout_chat'] = 'ਬਦਲਵਾਂ: ਚੈਟ ਦਾ ਸਮਾਂ (ਸਕਿੰਟ)';
$string['settings:failover_timeout_chat_desc'] = 'ਬਦਲਣ ਤੋਂ ਪਹਿਲਾਂ ਕਿਸੇ ਚੈਟ ਪ੍ਰਦਾਤਾ ਤੋਂ ਪਹਿਲੇ ਟੋਕਨ ਦੀ ਕਿੰਨੀ ਦੇਰ ਉਡੀਕ ਕਰਨੀ ਹੈ। ਮੂਲ 8 ਸਕਿੰਟ। ਘੱਟ ਮੁੱਲ ਹੌਲੀ ਪ੍ਰਦਾਤਾਵਾਂ ਤੋਂ ਤੇਜ਼ੀ ਨਾਲ ਹਟਦੇ ਹਨ, ਬਦਲੇ ਵਿੱਚ ਥੋੜ੍ਹੇ ਸਮੇਂ ਲਈ ਹੌਲੀ ਬੇਨਤੀਆਂ ਤੇ ਵੱਧ ਝੂਠੇ ਅਲਾਰਮ ਦਿੰਦੇ ਹਨ; ਵੱਧ ਮੁੱਲ ਲੜੀ ਨੂੰ ਮੁੱਖ ਪ੍ਰਦਾਤਾ ਨਾਲ ਲੰਬੇ ਸਮੇਂ ਤੱਕ ਰੱਖਦੇ ਹਨ। ਸਿਰਫ਼ ਤਾਂ ਲਾਗੂ ਹੁੰਦਾ ਹੈ ਜਦੋਂ <strong>ਹਰ ਕਾਲ ਤੇ ਬਦਲਵੇਂ ਵੱਲ ਜਾਣਾ</strong> ਚਾਲੂ ਹੋਵੇ।';
$string['settings:spend_notify_emails'] = 'ਖਰਚ ਚੇਤਾਵਨੀ ਪ੍ਰਾਪਤਕਰਤਾ';
$string['settings:spend_notify_emails_desc'] = 'ਕਾਮਿਆਂ ਨਾਲ ਵੱਖ ਕੀਤੇ ਈਮੇਲ ਪਤੇ, ਜਿਨ੍ਹਾਂ ਨੂੰ ਹੱਦ ਦੇ 80%, 95% ਅਤੇ 100% ਤੇ ਸੂਚਨਾ ਮਿਲੇਗੀ। ਸਾਰੇ ਸਾਈਟ ਪ੍ਰਸ਼ਾਸਕਾਂ ਨੂੰ ਸੂਚਿਤ ਕਰਨ ਲਈ ਖਾਲੀ ਛੱਡੋ।';
$string['settings:opt_cost_weight'] = 'ਅਨੁਕੂਲਕ: ਲਾਗਤ ਦਾ ਭਾਰ';
$string['settings:opt_cost_weight_desc'] = 'ਪ੍ਰਦਾਤਾਵਾਂ ਦੀ ਦਰਜਾਬੰਦੀ ਕਰਦੇ ਸਮੇਂ ਅਨੁਕੂਲਕ ਲਾਗਤ ਨੂੰ ਕਿੰਨਾ ਮਹੱਤਵ ਦੇਵੇ। 0.0 ਲਾਗਤ ਨੂੰ ਅਣਦੇਖਾ ਕਰਦਾ ਹੈ, 1.0 ਸਿਰਫ਼ ਲਾਗਤ ਦੇ ਆਧਾਰ ਤੇ ਅਨੁਕੂਲ ਕਰਦਾ ਹੈ। ਗੁਣਵੱਤਾ ਦੇ ਭਾਰ ਨਾਲ ਮਿਲਾ ਕੇ ਤੋਲਿਆ ਜਾਂਦਾ ਹੈ।';
$string['settings:opt_quality_weight'] = 'ਅਨੁਕੂਲਕ: ਗੁਣਵੱਤਾ ਦਾ ਭਾਰ';
$string['settings:opt_quality_weight_desc'] = 'ਪ੍ਰਦਾਤਾਵਾਂ ਦੀ ਦਰਜਾਬੰਦੀ ਕਰਦੇ ਸਮੇਂ ਅਨੁਕੂਲਕ ਸਿੱਖਿਆਰਥੀ ਦੀ ਸੰਤੁਸ਼ਟੀ (ਸਕਾਰਾਤਮਕ ਦਰਜਾਬੰਦੀਆਂ ਦਾ ਅਨੁਪਾਤ) ਨੂੰ ਕਿੰਨਾ ਮਹੱਤਵ ਦੇਵੇ। 0.0 ਗੁਣਵੱਤਾ ਨੂੰ ਅਣਦੇਖਾ ਕਰਦਾ ਹੈ।';
$string['settings:inactivity_reminder_enabled'] = 'ਨਿਸ਼ਕਿਰਿਆ ਹੋਣ ਦੇ ਚੇਤੇ';
$string['settings:inactivity_reminder_enabled_desc'] = 'ਜਿਹੜੇ ਸਿੱਖਿਆਰਥੀਆਂ ਨੇ ਤੈਅ ਕੀਤੇ ਦਿਨਾਂ ਤੱਕ ਆਪਣਾ ਕੋਰਸ ਨਹੀਂ ਖੋਲ੍ਹਿਆ, ਉਹਨਾਂ ਨੂੰ ਹਫ਼ਤਾਵਾਰੀ ਈਮੇਲ ਭੇਜਦਾ ਹੈ।';
$string['settings:inactivity_threshold_days'] = 'ਨਿਸ਼ਕਿਰਿਆ ਹੋਣ ਦੀ ਹੱਦ (ਦਿਨ)';
$string['settings:inactivity_threshold_days_desc'] = 'ਚੇਤਾ ਈਮੇਲ ਭੇਜਣ ਤੋਂ ਪਹਿਲਾਂ ਕਿੰਨੇ ਦਿਨ ਨਿਸ਼ਕਿਰਿਆ ਹੋਣੀ ਚਾਹੀਦੀ ਹੈ।';
$string['settings:voice_providers_heading'] = 'ਆਵਾਜ਼ ਪ੍ਰਦਾਤਾ (Realtime, TTS, STT)';
$string['settings:voice_providers_heading_desc'] = 'ਇੱਕ ਜਾਂ ਵੱਧ ਆਵਾਜ਼ API ਪ੍ਰਦਾਤਾ ਸੰਰਚਿਤ ਕਰੋ। ਇਹ ਸੈਟਿੰਗਾਂ ਉੱਪਰਲੇ ਚੈਟ ਪ੍ਰਦਾਤਾ ਅਤੇ RAG ਦੇ ਏਮਬੈਡਿੰਗ ਪ੍ਰਦਾਤਾ ਤੋਂ ਵੱਖਰੀਆਂ ਹਨ — ਆਵਾਜ਼ ਦੀ ਆਪਣੀ ਪ੍ਰਦਾਤਾ ਸੂਚੀ ਹੈ, ਕਿਉਂਕਿ ਇਸ ਵੇਲੇ ਸਿਰਫ਼ OpenAI ਅਤੇ xAI ਹੀ WebSocket ਆਧਾਰਿਤ Realtime, TTS ਅਤੇ STT ਅੰਤਬਿੰਦੂ ਦਿੰਦੇ ਹਨ। ਹੇਠਲੀਆਂ ਸੂਚੀਆਂ ਵਿੱਚੋਂ ਚੁਣੋ ਕਿ ਕਿਹੜਾ ਦਰਜ ਪ੍ਰਦਾਤਾ ਕਿਹੜੀ ਸਮਰੱਥਾ ਸੰਭਾਲੇਗਾ। ਜੇ ਕੋਈ ਕਤਾਰ ਨਿਰਧਾਰਤ ਨਾ ਹੋਵੇ, ਤਾਂ ਪੁਰਾਣਾ ਇੱਕ-ਕੁੰਜੀ ਵਿਹਾਰ ਲਾਗੂ ਹੁੰਦਾ ਹੈ (ਉੱਪਰਲੀ Realtime API ਕੁੰਜੀ ਜਾਂ ਮੁੱਖ OpenAI ਕੁੰਜੀ)। ਜਿਹੜੀ ਸਾਈਟ ਚੈਟ ਲਈ Together AI / Anthropic / DeepSeek / Gemini / Mistral ਵਰਤਦੀ ਹੈ, ਉਸਨੂੰ ਆਵਾਜ਼ ਚਲਾਉਣ ਲਈ ਇੱਥੇ ਘੱਟੋ-ਘੱਟ ਇੱਕ ਕਤਾਰ ਸੰਰਚਿਤ ਕਰਨੀ ਪਵੇਗੀ।';
$string['settings:voice_active_realtime'] = 'ਸਰਗਰਮ Realtime ਪ੍ਰਦਾਤਾ';
$string['settings:voice_active_realtime_desc'] = 'ਕਿਹੜਾ ਸੰਰਚਿਤ ਆਵਾਜ਼ ਪ੍ਰਦਾਤਾ Realtime ਆਵਾਜ਼ ਏਜੰਟ ਦੇ ਸੈਸ਼ਨ ਸੰਭਾਲੇਗਾ।';
$string['settings:voice_active_tts'] = 'ਸਰਗਰਮ TTS ਪ੍ਰਦਾਤਾ';
$string['settings:voice_active_tts_desc'] = 'ਕਿਹੜਾ ਸੰਰਚਿਤ ਆਵਾਜ਼ ਪ੍ਰਦਾਤਾ ਏਆਈ ਦੇ ਜਵਾਬ ਉੱਚੀ ਪੜ੍ਹ ਕੇ ਸੁਣਾਏਗਾ।';
$string['settings:voice_active_stt'] = 'ਸਰਗਰਮ STT ਪ੍ਰਦਾਤਾ';
$string['settings:voice_active_stt_desc'] = 'ਕਿਹੜਾ ਪ੍ਰਦਾਤਾ ਸਿੱਖਿਆਰਥੀ ਦੀ ਬੋਲੀ ਨੂੰ ਲਿਖਤ ਵਿੱਚ ਬਦਲੇਗਾ। ਹੇਠਾਂ ਸੰਰਚਿਤ ਹੋਣ ਤੇ ਪਹਿਲਾਂ ਆਪਣੇ ਸਰਵਰ ਵਾਲੇ Whisper ਨੂੰ ਤਰਜੀਹ ਦੇਣ ਲਈ, ਫਿਰ ਆਵਾਜ਼ ਪ੍ਰਦਾਤਾਵਾਂ ਦੀ ਪਹਿਲੀ ਕਤਾਰ ਜਾਂ ਪੁਰਾਣੀ ਕੁੰਜੀ ਵਰਤਣ ਲਈ ਖਾਲੀ ਛੱਡੋ।';
$string['settings:stt_selfhosted_enabled'] = 'ਆਪਣੇ ਸਰਵਰ ਤੇ ਲਿਪੀਅੰਤਰਨ ਚਾਲੂ ਕਰੋ';
$string['settings:stt_selfhosted_enabled_desc'] = 'ਆਵਾਜ਼ ਇਨਪੁੱਟ ਅਤੇ Soapbox ਲਈ ਬੋਲੀ-ਤੋਂ-ਲਿਖਤ ਦੇ ਰਾਹ ਵਜੋਂ ਹੇਠਲਾ ਆਪਣਾ Whisper ਸਰਵਰ ਵਰਤਦਾ ਹੈ। ਹੇਠਾਂ ਸਰਵਰ ਦਾ ਪਤਾ ਲੋੜੀਂਦਾ ਹੈ। ਬੰਦ ਹੋਣ ਤੇ, ਪਤਾ ਸੈੱਟ ਹੋਣ ਦੇ ਬਾਵਜੂਦ ਲਿਪੀਅੰਤਰਨ ਹੋਸਟ ਕੀਤੇ ਰਾਹ (OpenAI Whisper) ਜਾਂ ਬ੍ਰਾਊਜ਼ਰ ਦੇ ਰਾਹ ਤੇ ਵਾਪਸ ਚਲਾ ਜਾਂਦਾ ਹੈ।';
$string['settings:stt_selfhosted_warm'] = 'Soapbox ਰਿਕਾਰਡਿੰਗ ਸ਼ੁਰੂ ਹੋਣ ਤੇ ਤਿਆਰ ਕਰੋ';
$string['settings:stt_selfhosted_warm_desc'] = 'ਚਾਲੂ ਹੋਣ ਤੇ, Soapbox ਰਿਕਾਰਡਿੰਗ ਸ਼ੁਰੂ ਕਰਨ ਨਾਲ ਆਪਣੇ ਲਿਪੀਅੰਤਰਨ ਸਰਵਰ ਨੂੰ ਇੱਕ ਹਲਕੀ "ਤਿਆਰੀ" ਬੇਨਤੀ ਭੇਜੀ ਜਾਂਦੀ ਹੈ (ਜਿੰਨਾ ਸੰਭਵ ਹੋਵੇ), ਤਾਂ ਜੋ ਸਿਫ਼ਰ ਤੱਕ ਸੁੰਗੜਨ ਵਾਲਾ ਹੋਸਟ (ਜਿਵੇਂ Cloud Run) ਸਿੱਖਿਆਰਥੀ ਦੇ ਰਿਕਾਰਡ ਕਰਦੇ ਸਮੇਂ ਹੀ ਚਾਲੂ ਹੋ ਸਕੇ — ਇਸ ਤਰ੍ਹਾਂ ਠੰਢੀ ਸ਼ੁਰੂਆਤ ਦੀ ਦੇਰੀ ਜਮ੍ਹਾਂ ਕਰਨ ਵੇਲੇ ਦੇ ਲਿਪੀਅੰਤਰਨ ਤੋਂ ਲੁਕੀ ਰਹਿੰਦੀ ਹੈ। ਜੇ ਉੱਪਰ ਆਪਣੇ ਸਰਵਰ ਦਾ ਪਤਾ ਸੈੱਟ ਨਾ ਹੋਵੇ ਤਾਂ ਕੋਈ ਅਸਰ ਨਹੀਂ। ਮੂਲ ਰੂਪ ਵਿੱਚ ਬੰਦ।';
$string['settings:voice_tab_enabled'] = 'ਆਵਾਜ਼ ਟੈਬ ਚਾਲੂ ਕਰੋ';
$string['settings:voice_tab_enabled_desc'] = 'ਹੇਠਲੀ ਨੇਵੀਗੇਸ਼ਨ ਪੱਟੀ ਵਿੱਚ ਆਵਾਜ਼ ਟੈਬ ਦਿਖਾਉਂਦਾ ਹੈ। ਬੰਦ ਹੋਣ ਤੇ ਸਿੱਖਿਆਰਥੀਆਂ ਨੂੰ ਸਿਰਫ਼ ਚੈਟ ਅਤੇ ਨੋਟ ਟੈਬ ਦਿਖਦੇ ਹਨ। ਆਵਾਜ਼ ਦੀਆਂ ਸਮਰੱਥਾਵਾਂ (ਗੱਲਬਾਤ ਅਭਿਆਸ, ਉਚਾਰਨ ਅਭਿਆਸ) ਵੱਖਰੇ ਤੌਰ ਤੇ ਚਾਲੂ ਹੋਣ ਤੇ ਗੱਲਬਾਤ ਸ਼ੁਰੂ ਕਰਨ ਵਾਲੇ ਸੁਝਾਵਾਂ ਰਾਹੀਂ ਪਹੁੰਚਯੋਗ ਰਹਿੰਦੀਆਂ ਹਨ।';
$string['settings:soapbox_heading'] = 'Soapbox';
$string['settings:soapbox_heading_desc'] = 'ਜ਼ੁਬਾਨੀ ਪੇਸ਼ਕਾਰੀ ਦਾ ਅਭਿਆਸ: ਰਿਕਾਰਡਿੰਗਾਂ ਦਾ ਲਿਪੀਅੰਤਰਨ ਕਿਵੇਂ ਹੋਵੇਗਾ ਅਤੇ ਕਿਸ ਮਾਪਦੰਡ ਅਨੁਸਾਰ ਅੰਕ ਮਿਲਣਗੇ। ਸਿੱਖਿਆ-ਸ਼ਾਸਤਰ ਭਾਗ ਦੇ Soapbox ਸਵਿੱਚ ਨਾਲ ਹਰ ਕੋਰਸ ਲਈ Soapbox ਚਾਲੂ ਕਰੋ।';
$string['settings:soapbox_max_seconds'] = 'ਵੱਧ ਤੋਂ ਵੱਧ Soapbox ਰਿਕਾਰਡਿੰਗ ਦੀ ਲੰਬਾਈ (ਸਕਿੰਟ)';
$string['settings:soapbox_max_seconds_desc'] = 'ਕਿਸੇ ਵੀ ਕੰਮ ਲਈ ਰਿਕਾਰਡਿੰਗ ਦੀ ਲੰਬਾਈ ਦੀ ਪੂਰਨ ਉਪਰਲੀ ਹੱਦ। ਅਧਿਆਪਕ ਇਸ ਤੋਂ ਛੋਟੀ ਹੱਦ ਤੈਅ ਕਰ ਸਕਦੇ ਹਨ। ਮੂਲ 720 (12 ਮਿੰਟ)।';
$string['settings:soapbox_max_recordings'] = 'ਪ੍ਰਤੀ ਸਿੱਖਿਆਰਥੀ ਅਤੇ ਕੰਮ ਵੱਧ ਤੋਂ ਵੱਧ Soapbox ਰਿਕਾਰਡਿੰਗਾਂ';
$string['settings:soapbox_max_recordings_desc'] = 'ਪ੍ਰਤੀ ਕੰਮ ਕੋਸ਼ਿਸ਼ਾਂ ਦੀ ਸੈਟਿੰਗ ਜੋ ਵੀ ਹੋਵੇ, ਇੱਕ ਸਿੱਖਿਆਰਥੀ ਕਿਸੇ ਕੰਮ ਲਈ ਵੱਧ ਤੋਂ ਵੱਧ ਜਿੰਨੀਆਂ ਰਿਕਾਰਡਿੰਗਾਂ ਕਰ ਸਕਦਾ ਹੈ, ਉਸਦੀ ਪੂਰਨ ਹੱਦ। ਮੂਲ 3।';
$string['settings:soapbox_retention_days'] = 'Soapbox ਰਿਕਾਰਡਿੰਗਾਂ ਰੱਖਣ ਦੀ ਮਿਆਦ (ਦਿਨ)';
$string['settings:soapbox_retention_days_desc'] = 'ਆਪਣੇ ਆਪ ਮਿਟਾਏ ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ ਰਿਕਾਰਡਿੰਗ ਕਿੰਨੀ ਦੇਰ ਰੱਖੀ ਜਾਵੇਗੀ; ਲਿਪੀਅੰਤਰਨ, ਅੰਕ ਅਤੇ ਫੀਡਬੈਕ ਰੱਖੇ ਜਾਂਦੇ ਹਨ। 1–28 ਦਿਨਾਂ ਤੱਕ ਸੀਮਤ। ਡੇਟਾ ਘੱਟ ਰੱਖਣ ਲਈ ਜਿੰਨਾ ਘੱਟ ਓਨਾ ਚੰਗਾ। ਮੂਲ 7।';
$string['settings:soapbox_video_quality'] = 'Soapbox ਵੀਡੀਓ ਦੀ ਗੁਣਵੱਤਾ';
$string['settings:soapbox_video_quality_desc'] = 'ਰਿਕਾਰਡਿੰਗ ਦਾ ਰੈਜ਼ੋਲਿਊਸ਼ਨ ਅਤੇ ਬਿੱਟਰੇਟ। ਇਹੀ ਲਾਗਤ ਅਤੇ ਬੈਂਡਵਿਡਥ ਦਾ ਮੁੱਖ ਕਾਰਨ ਹੈ; ਦਰਮਿਆਨੇ ਦ੍ਰਿਸ਼ ਵਿੱਚ ਦਿਖਦਾ ਬੁਲਾਰਾ ਮਿਆਰੀ ਗੁਣਵੱਤਾ ਵਿੱਚ ਵੀ ਸਾਫ਼ ਦਿਖਦਾ ਹੈ। ਕਮਜ਼ੋਰ ਕਨੈਕਸ਼ਨਾਂ ਲਈ ਘੱਟ ਗੁਣਵੱਤਾ ਢੁਕਵੀਂ ਹੈ; ਉੱਚ ਗੁਣਵੱਤਾ ਸਿਰਫ਼ ਤਾਂ ਜਦੋਂ ਦ੍ਰਿਸ਼ ਵੇਰਵੇ ਮਹੱਤਵਪੂਰਨ ਹੋਣ।';
$string['settings:soapbox_storage_bucket'] = 'Soapbox ਸਟੋਰੇਜ ਬਾਲਟੀ';
$string['settings:soapbox_storage_bucket_desc'] = 'ਰਿਕਾਰਡਿੰਗਾਂ ਲਈ S3 ਬਾਲਟੀ। ਮੂਲ: ਸਾਂਝੀ ਪੁਰਾਲੇਖ ਬਾਲਟੀ।';
$string['settings:soapbox_storage_region'] = 'Soapbox ਸਟੋਰੇਜ ਖੇਤਰ';
$string['settings:soapbox_storage_region_desc'] = 'ਬਾਲਟੀ ਦਾ AWS ਖੇਤਰ, ਜਿਵੇਂ us-east-1।';
$string['settings:soapbox_storage_prefix'] = 'Soapbox ਸਟੋਰੇਜ ਕੁੰਜੀ ਅਗੇਤਰ';
$string['settings:soapbox_storage_prefix_desc'] = 'ਬਾਲਟੀ ਦੇ ਅੰਦਰ ਕੁੰਜੀਆਂ ਦਾ ਅਗੇਤਰ। ਰਿਕਾਰਡਿੰਗਾਂ ਇਸ ਰਾਹ ਦੇ ਹੇਠਾਂ ਸੰਭਾਲੀਆਂ ਜਾਂਦੀਆਂ ਹਨ, ਤਾਂ ਜੋ ਜੀਵਨ-ਚੱਕਰ ਨਿਯਮ ਉਹਨਾਂ ਨੂੰ ਨਿਸ਼ਾਨਾ ਬਣਾ ਸਕੇ।';
