$string['settings:survey_heading'] = 'ਸਿੱਖਿਆਰਥੀ ਸਰਵੇਖਣ';
$string['settings:survey_heading_desc'] = 'ਚੈਟ ਦੇ ਅੰਦਰਲਾ ਸਿੱਖਿਆਰਥੀ ਅਨੁਭਵ ਸਰਵੇਖਣ ਸੰਰਚਿਤ ਕਰੋ। <a href="{$a}" class="btn btn-sm btn-outline-primary ml-2">ਸਰਵੇਖਣ ਦੇ ਸਵਾਲ ਸੰਪਾਦਿਤ ਕਰੋ &rarr;</a>';
$string['settings:survey_enabled'] = 'ਸਰਵੇਖਣ ਚਾਲੂ ਕਰੋ';
$string['settings:survey_enabled_desc'] = 'ਚਾਲੂ ਹੋਣ ਤੇ ਸਿੱਖਿਆਰਥੀਆਂ ਨੂੰ ਏਆਈ ਟਿਊਟਰ ਨਾਲ ਆਪਣੇ ਅਨੁਭਵ ਬਾਰੇ ਸਰਵੇਖਣ ਭਰਨ ਦੀ ਪੇਸ਼ਕਸ਼ ਕੀਤੀ ਜਾਵੇਗੀ।';
$string['settings:survey_trigger_messages'] = 'N ਸੁਨੇਹਿਆਂ ਤੋਂ ਬਾਅਦ ਦਿਖਾਓ';
$string['settings:survey_trigger_messages_desc'] = 'ਕਿਸੇ ਕੋਰਸ ਵਿੱਚ ਸਿੱਖਿਆਰਥੀ ਵੱਲੋਂ ਇੰਨੇ ਸੁਨੇਹੇ ਭੇਜਣ ਤੋਂ ਬਾਅਦ ਸਰਵੇਖਣ ਦਾ ਸੱਦਾ ਦਿਖਾਉਂਦਾ ਹੈ। ਸਿਰਫ਼ ਹੱਥੀਂ ਚਲਾਉਣ ਤੇ ਦਿਖਾਉਣ ਲਈ 0 ਸੈੱਟ ਕਰੋ।';
$string['settings:survey_frequency'] = 'ਪ੍ਰਤੀ ਵਰਤੋਂਕਾਰ ਸਰਵੇਖਣ ਦੀ ਬਾਰੰਬਾਰਤਾ';
$string['settings:survey_frequency_desc'] = 'ਹਰ ਕੋਰਸ ਵਿੱਚ ਇੱਕ ਸਿੱਖਿਆਰਥੀ ਨੂੰ ਕਿੰਨੀ ਵਾਰ ਸਰਵੇਖਣ ਭਰਨ ਦਾ ਸੱਦਾ ਦਿੱਤਾ ਜਾ ਸਕਦਾ ਹੈ।';
$string['settings:rubric_heading'] = 'ਅਭਿਆਸ ਦੇ ਮਾਪਦੰਡ';
$string['settings:rubric_heading_desc'] = 'ਗੱਲਬਾਤ ਅਤੇ ਉਚਾਰਨ ਅਭਿਆਸ ਸੈਸ਼ਨਾਂ ਲਈ ਅੰਕ ਦੇਣ ਦੇ ਮਾਪਦੰਡ ਸੰਰਚਿਤ ਕਰੋ। ਅਭਿਆਸ ਸੈਸ਼ਨ ਦੇ ਅੰਤ ਤੇ ਸਿੱਖਿਆਰਥੀਆਂ ਨੂੰ ਏਆਈ ਵੱਲੋਂ ਬਣਾਏ ਅੰਕ ਅਤੇ ਫੀਡਬੈਕ ਮਿਲਦੇ ਹਨ। <a href="{$a}" class="btn btn-sm btn-outline-primary ml-2">ਮਾਪਦੰਡ ਸੰਪਾਦਿਤ ਕਰੋ &rarr;</a>';
$string['settings:practice_scoring_enabled'] = 'ਅਭਿਆਸ ਅੰਕ ਦੇਣਾ ਚਾਲੂ ਕਰੋ';
