$string['settings:footer_courses_url_desc'] = 'ਕੋਰਸ ਲਿੰਕ ਦੀ ਮੰਜ਼ਿਲ (ਨਵੀਂ ਟੈਬ ਵਿੱਚ ਖੁੱਲ੍ਹਦਾ ਹੈ)। ਇਹ ਖਾਨਾ ਖਾਲੀ ਹੋਵੇ ਤਾਂ ਲਿੰਕ ਲੁਕ ਜਾਂਦਾ ਹੈ।';
$string['settings:feedback_link_label'] = 'ਫੀਡਬੈਕ ਲਿੰਕ ਦਾ ਲੇਬਲ';
$string['settings:feedback_link_label_desc'] = 'ਹੇਠਲੇ ਹਿੱਸੇ ਦੇ ਫੀਡਬੈਕ ਲਿੰਕ ਦੀ ਲਿਖਤ ਬਦਲਦਾ ਹੈ, ਜਿਵੇਂ "[[tutorshort]] ਬਾਰੇ ਵਿਚਾਰ ਆਈਟੀ ਟੀਮ ਨੂੰ ਭੇਜੋ"। ਅਨੁਵਾਦਿਤ ਮੂਲ ਲੇਬਲ "ਫੀਡਬੈਕ" ਵਰਤਣ ਲਈ ਖਾਲੀ ਛੱਡੋ।';
$string['settings:feedback_panel_intro'] = 'ਫੀਡਬੈਕ ਪੈਨਲ ਦੀ ਭੂਮਿਕਾ';
$string['settings:feedback_panel_intro_desc'] = 'ਫੀਡਬੈਕ ਪੈਨਲ ਦੇ ਉੱਪਰ ਦਿਖਦੀ ਭੂਮਿਕਾ ਵਾਲੀ ਲਾਈਨ। ਸਪੱਸ਼ਟ ਕਰਦੀ ਹੈ ਕਿ ਵਿਚਾਰ ਕਿੱਥੇ ਜਾਂਦੇ ਹਨ। ਭੂਮਿਕਾ ਵਾਲੀ ਲਾਈਨ ਨਾ ਦਿਖਾਉਣ ਲਈ ਖਾਲੀ ਛੱਡੋ।';
$string['settings:quiz_provider'] = 'ਕਵਿਜ਼ ਸਹਾਇਕ ਦਾ ਪ੍ਰਦਾਤਾ';
$string['settings:quiz_provider_desc'] = 'ਕਵਿਜ਼ ਬਣਾਉਣ ਲਈ ਪ੍ਰਦਾਤਾ ਦੀ ਆਈਡੀ (ਜਿਵੇਂ <code>claude</code> ਜਾਂ <code>openai</code>)। ਤੁਲਨਾ ਪ੍ਰਦਾਤਾਵਾਂ ਦੀ ਕਿਸੇ ਕਤਾਰ ਨਾਲ ਮੇਲ ਖਾਣੀ ਚਾਹੀਦੀ ਹੈ। ਚੈਟ ਪ੍ਰਦਾਤਾ ਵਰਤਣ ਲਈ ਖਾਲੀ ਛੱਡੋ।';
$string['settings:quiz_model'] = 'ਕਵਿਜ਼ ਸਹਾਇਕ ਦਾ ਮਾਡਲ';
