$string['settings:display_name_desc'] = 'ਏਆਈ ਸਹਾਇਕ ਦਾ ਪੂਰਾ ਨਾਮ, ਜਿਵੇਂ ਸੁਆਗਤੀ ਸੁਨੇਹਿਆਂ ਅਤੇ ਸੁਆਗਤ ਸਕਰੀਨ ਤੇ ਦਿਖਦਾ ਹੈ (ਜਿਵੇਂ "ਆਨਲਾਈਨ ਸਿੱਖਣ ਸਹਾਇਕ")।';
$string['settings:short_name'] = 'ਸਹਾਇਕ ਦਾ ਛੋਟਾ ਨਾਮ';
