$string['settings:welcome_message'] = 'ਸੁਆਗਤ ਸਕਰੀਨ ਦਾ ਸੁਨੇਹਾ';
$string['settings:welcome_message_desc'] = 'ਪਹਿਲੀ ਫੇਰੀ ਤੇ ਸੁਆਗਤ ਸਕਰੀਨ ਤੇ ਦਿਖਦਾ ਸੁਨੇਹਾ। ਸਿੱਖਿਆਰਥੀ ਦੇ ਨਾਮ ਲਈ <code>{{firstname}}</code> ਅਤੇ ਕੋਰਸ ਦੇ ਨਾਮ ਲਈ <code>{{coursename}}</code> ਵਰਤੋ। ਮੂਲ ਲਿਖਤ ਲਈ ਖਾਲੀ ਛੱਡੋ।';
$string['settings:chat_greeting'] = 'ਚੈਟ ਦਾ ਸੁਆਗਤੀ ਸੁਨੇਹਾ';
$string['settings:chat_greeting_desc'] = 'ਚੈਟ ਵਿੰਡੋ ਖੁੱਲ੍ਹਣ ਤੇ ਦਿਖਦਾ ਸੁਆਗਤੀ ਸੁਨੇਹਾ। ਸਿੱਖਿਆਰਥੀ ਦੇ ਨਾਮ ਲਈ <code>{{firstname}}</code> ਅਤੇ ਕੋਰਸ ਦੇ ਨਾਮ ਲਈ <code>{{coursename}}</code> ਵਰਤੋ। ਮੂਲ ਲਿਖਤ ਲਈ ਖਾਲੀ ਛੱਡੋ।';
$string['settings:customavatars'] = 'ਆਪਣੇ ਅਵਤਾਰ';
$string['settings:customavatars_desc'] = 'ਉੱਪਰਲੀ ਅਵਤਾਰ ਸੂਚੀ ਵਿੱਚ ਜੋੜਨ ਲਈ ਇੱਥੇ ਵਰਗਾਕਾਰ PNG ਜਾਂ SVG ਤਸਵੀਰਾਂ ਅੱਪਲੋਡ ਕਰੋ। ਅੱਪਲੋਡ ਕੀਤੀ ਹਰ ਫਾਈਲ ਚੁਣਨਯੋਗ ਮੂਲ ਬਣ ਜਾਂਦੀ ਹੈ ("Custom:" ਅਗੇਤਰ ਨਾਲ)। ਡ੍ਰੌਪਡਾਊਨ ਵਿੱਚੋਂ ਹਟਾਉਣ ਲਈ ਫਾਈਲ ਇਸ ਸੂਚੀ ਵਿੱਚੋਂ ਮਿਟਾਓ। ਸੁਝਾਅ: 256×256 ਦੀ PNG ਰੈਟੀਨਾ ਸਕਰੀਨਾਂ ਤੇ ਸਾਫ਼ ਦਿਖਦੀ ਹੈ।';
$string['settings:anomaly_digest_heading'] = 'Learning Radar — ਅਸਧਾਰਨਤਾ ਸਾਰ';
$string['settings:anomaly_digest_heading_desc'] = 'ਰੋਜ਼ਾਨਾ ਜਾਂਚ, ਜੋ ਨਕਾਰਾਤਮਕ ਦਰਜਾਬੰਦੀਆਂ, ਟੋਕਨ ਖਰਚ ਅਤੇ ਇਮਾਨਦਾਰੀ ਦੇ ਨਿਸ਼ਾਨਾਂ ਦੇ ਚੱਲਦੇ ਸਮੇਂ-ਖੰਡਾਂ ਦੀ ਤੁਲਨਾ ਕਰਦੀ ਹੈ। ਕੋਈ ਸੂਚਕ ਤੈਅ ਹੱਦ ਪਾਰ ਕਰੇ ਤਾਂ ਸੰਰਚਿਤ ਚੈਨਲਾਂ ਤੇ ਸਾਰ ਭੇਜਿਆ ਜਾਂਦਾ ਹੈ। ਪੁੱਛਗਿੱਛ-ਵਾਰ ਨਿਯਤ ਰਿਪੋਰਟਾਂ ਲਈ [[tutorshort]] ਵਿਸ਼ਲੇਸ਼ਣ ਪੰਨੇ ਦਾ ਸਮਾਂ-ਸਾਰਣੀ ਪੈਨਲ ਵਰਤੋ।';
$string['settings:anomaly_digest_enabled'] = 'ਅਸਧਾਰਨਤਾ ਸਾਰ ਚਾਲੂ ਕਰੋ';
$string['settings:anomaly_digest_enabled_desc'] = 'ਰੋਜ਼ਾਨਾ ਅਸਧਾਰਨਤਾ ਸਾਰ ਦਾ ਕੰਮ ਚਲਾਉਂਦਾ ਹੈ। ਮੂਲ ਰੂਪ ਵਿੱਚ ਚੁੱਪ — ਸਿਰਫ਼ ਤਾਂ ਚੱਲਦਾ ਹੈ ਜਦੋਂ ਕੋਈ ਸੂਚਕ ਹੱਦ ਪਾਰ ਕਰੇ।';
$string['settings:anomaly_digest_threshold_pct'] = 'ਚੇਤਾਵਨੀ ਦੀ ਹੱਦ (%)';
$string['settings:anomaly_digest_threshold_pct_desc'] = 'ਤਾਜ਼ਾ ਅਤੇ ਪਿਛਲੇ ਸਮੇਂ-ਖੰਡ ਵਿਚਕਾਰ ਪ੍ਰਤੀਸ਼ਤ ਬਦਲਾਅ, ਜੋ ਚੇਤਾਵਨੀ ਚਲਾਉਂਦਾ ਹੈ। ਮੂਲ: 50।';
$string['settings:anomaly_digest_recipient_email'] = 'ਪ੍ਰਾਪਤਕਰਤਾ ਦਾ ਈਮੇਲ ਪਤਾ';
$string['settings:anomaly_digest_recipient_email_desc'] = 'ਅਸਧਾਰਨਤਾ ਸਾਰ ਪ੍ਰਾਪਤ ਕਰਨ ਵਾਲਾ ਈਮੇਲ ਪਤਾ। ਸਾਈਟ ਪ੍ਰਸ਼ਾਸਕ ਦਾ ਪਤਾ ਵਰਤਣ ਲਈ ਖਾਲੀ ਛੱਡੋ।';
$string['settings:anomaly_digest_slack_webhook'] = 'Slack ਆਉਣ ਵਾਲਾ webhook ਪਤਾ';
$string['settings:anomaly_digest_slack_webhook_desc'] = 'ਵਿਕਲਪਿਕ Slack ਆਉਣ ਵਾਲਾ webhook ਪਤਾ। ਸਾਰ Slack ਬਲਾਕ ਸੁਨੇਹੇ ਵਜੋਂ ਪ੍ਰਕਾਸ਼ਿਤ ਹੁੰਦਾ ਹੈ।';
$string['settings:anomaly_digest_teams_webhook'] = 'Microsoft Teams ਆਉਣ ਵਾਲਾ webhook ਪਤਾ';
$string['settings:anomaly_digest_teams_webhook_desc'] = 'ਵਿਕਲਪਿਕ Teams ਆਉਣ ਵਾਲਾ webhook ਪਤਾ। ਸਾਰ Office 365 ਕਨੈਕਟਰ ਕਾਰਡ ਵਜੋਂ ਪ੍ਰਕਾਸ਼ਿਤ ਹੁੰਦਾ ਹੈ।';

$string['settings:embed_query_model'] = 'ਪੁੱਛਗਿੱਛ ਏਮਬੈਡਿੰਗ ਮਾਡਲ (ਉੱਚ ਪੱਧਰੀ)';
$string['settings:embed_query_model_desc'] = 'ਜਦੋਂ ਤੱਕ ਤੁਹਾਨੂੰ ਪੱਕਾ ਪਤਾ ਨਾ ਹੋਵੇ ਕਿ ਲੋੜ ਹੈ, ਇਸਨੂੰ ਖਾਲੀ ਛੱਡੋ। ਆਮ ਤੌਰ \'ਤੇ ਪੁੱਛਗਿੱਛਾਂ ਅਤੇ ਕੋਰਸ ਸਮੱਗਰੀ ਇੱਕੋ ਮਾਡਲ ਨਾਲ ਏਮਬੈਡ ਕੀਤੀ ਜਾਂਦੀ ਹੈ, ਜੋ ਹਰ ਹਾਲਤ ਵਿੱਚ ਸੁਰੱਖਿਅਤ ਇੱਕੋ-ਇੱਕ ਚੋਣ ਹੈ: ਵੱਖ-ਵੱਖ ਮਾਡਲਾਂ ਦੇ ਵੈਕਟਰਾਂ ਦੀ ਤੁਲਨਾ ਨਹੀਂ ਕੀਤੀ ਜਾ ਸਕਦੀ, ਅਤੇ ਉਹਨਾਂ ਨੂੰ ਰਲਾਉਣ ਨਾਲ ਗਲਤੀ ਦੀ ਥਾਂ ਭਰੋਸੇਯੋਗ ਲੱਗਣ ਵਾਲੇ ਪਰ ਅਰਥਹੀਣ ਨਤੀਜੇ ਮਿਲਦੇ ਹਨ। ਇਸਨੂੰ ਸਿਰਫ਼ ਉਦੋਂ ਸੈੱਟ ਕਰੋ ਜਦੋਂ ਦੋਵੇਂ ਮਾਡਲ ਇੱਕੋ ਏਮਬੈਡਿੰਗ ਸਪੇਸ ਸਾਂਝੀ ਕਰਦੇ ਹੋਣ — ਹਾਲੇ Voyage 4 ਪਰਿਵਾਰ (voyage-4-large, voyage-4, voyage-4-lite, voyage-4-nano), ਜਿਨ੍ਹਾਂ ਦੀ ਆਪਸੀ ਬਦਲਵੀਂ ਵਰਤੋਂ ਦਸਤਾਵੇਜ਼ੀ ਹੈ। ਫ਼ਾਇਦਾ ਇਹ ਹੈ ਕਿ ਤੁਸੀਂ ਪੂਰੇ ਕੋਰਸ ਕੈਟਾਲਾਗ ਨੂੰ ਦੁਬਾਰਾ ਏਮਬੈਡ ਕੀਤੇ ਬਿਨਾਂ ਬਾਅਦ ਵਿੱਚ ਪੁੱਛਗਿੱਛ ਮਾਡਲ ਬਦਲ ਸਕਦੇ ਹੋ। ਜੇ ਮਾਡਲ ਤੁਲਨਾਯੋਗ ਨਾ ਨਿਕਲਣ, ਤਾਂ ਪ੍ਰਾਪਤੀ ਇੱਕ ਚਿਤਾਵਨੀ ਦਰਜ ਕਰਦੀ ਹੈ ਅਤੇ ਗਲਤ ਹਿੱਸੇ ਦੇਣ ਦੀ ਥਾਂ ਉਸ ਕੋਰਸ ਲਈ ਕੁਝ ਵੀ ਨਹੀਂ ਦਿੰਦੀ।';
$string['settings:embed_dtype'] = 'ਸੰਭਾਲੇ ਵੈਕਟਰ ਦੀ ਸ਼ੁੱਧਤਾ';
$string['settings:embed_dtype_desc'] = 'ਹਰ ਸੰਭਾਲੇ ਵੈਕਟਰ ਕਿੰਨੀ ਥਾਂ ਲੈਂਦਾ ਹੈ। ਘੱਟ ਸ਼ੁੱਧਤਾ ਬਹੁਤ ਸਾਰੀ ਡਿਸਕ ਬਚਾਉਂਦੀ ਹੈ ਪਰ ਪ੍ਰਾਪਤੀ ਦੀ ਸਹੀਪਣ ਕੁਝ ਘਟਦੀ ਹੈ। <strong>ਇਸਨੂੰ ਬਦਲਣ ਲਈ ਪੂਰੀ ਮੁੜ-ਸੂਚੀਕਰਨ ਲੋੜੀਂਦੀ ਹੈ</strong> — ਫਾਰਮੈਟ ਇੱਕ-ਦੂਜੇ ਦੀ ਥਾਂ ਪੜ੍ਹੇ ਨਹੀਂ ਜਾ ਸਕਦੇ, ਅਤੇ ਪੁਰਾਣੇ ਫਾਰਮੈਟ ਵਿੱਚ ਸੰਭਾਲਿਆ ਕੋਈ ਵੀ ਕੋਰਸ ਮੁੜ-ਸੂਚੀਬੱਧ ਹੋਣ ਤੱਕ ਛੱਡ ਦਿੱਤਾ ਜਾਵੇਗਾ (ਲੌਗ ਵਿੱਚ ਚਿਤਾਵਨੀ ਨਾਲ)। ਸਿਰਫ਼ ਕੁਆਂਟਾਈਜ਼ੇਸ਼ਨ ਸਮਰਥਿਤ ਪ੍ਰਦਾਤਾ ਇਸਦੀ ਪਾਲਣਾ ਕਰਦੇ ਹਨ; ਬਾਕੀ ਸਦਾ ਪੂਰੀ ਸ਼ੁੱਧਤਾ ਵਿੱਚ ਸੰਭਾਲਦੇ ਹਨ।';
$string['settings:embed_dtype_float'] = 'ਪੂਰੀ ਸ਼ੁੱਧਤਾ (ਸਭ ਤੋਂ ਵੱਡੀ, ਸਭ ਤੋਂ ਸਹੀ)';
