$string['rec:verdict_no_material_gain'] = 'ਕੋਈ ਠੋਸ ਲਾਭ ਨਹੀਂ';
$string['rec:verdict_not_comparable'] = 'ਤੁਲਨਾਯੋਗ ਨਹੀਂ';
$string['rec:verdict_quality_gain'] = 'ਬਿਹਤਰ, ਮਹਿੰਗਾ ਨਹੀਂ';
$string['settings:bench_default_samples'] = 'ਪ੍ਰਤੀ ਰਨ ਪ੍ਰੌਂਪਟ';
$string['settings:bench_default_samples_desc'] = 'ਵੈੱਬ ਤੋਂ ਕਤਾਰ ਵਿੱਚ ਲਗਾਇਆ benchmark ਕਿੰਨੇ ਪ੍ਰੌਂਪਟ ਭੇਜਦਾ ਹੈ। ਹਰ ਪ੍ਰੌਂਪਟ ਦੋ ਲਾਈਵ ਮਾਡਲ ਕਾਲਾਂ ਦਾ ਖਰਚ ਕਰਦਾ ਹੈ — ਜਵਾਬ ਅਤੇ ਜੱਜ — ਸੋ ਇਹੀ ਕੀਮਤ ਦਾ ਡਾਇਲ ਹੈ। ਕੋਡ ਵਿੱਚ 50 ਉੱਤੇ ਸੀਮਿਤ, ਜੋ ਗੋਲਡਨ ਸੈੱਟ ਦਾ ਆਕਾਰ ਵੀ ਹੈ ਅਤੇ ਇੱਕ ਰਨ ਨੂੰ ਪ੍ਰਦਾਤਾ ਦੀ ਦਰ ਹੱਦ ਦੇ ਅੰਦਰ ਰੱਖਦਾ ਹੈ।';
$string['settings:bench_heading'] = 'ਮਾਡਲ Benchmark';
$string['settings:bench_heading_desc'] = 'ਇੱਕ benchmark ਰਨ 50 ਪ੍ਰੌਂਪਟਾਂ ਦੇ ਜਵਾਬ ਦਿੰਦਾ ਹੈ ਅਤੇ ਇੱਕ ਜੱਜ ਮਾਡਲ ਹਰ ਜਵਾਬ ਨੂੰ ਰੂਬਰਿਕ ਦੇ ਵਿਰੁੱਧ ਅੰਕ ਦਿੰਦਾ ਹੈ, ਫਿਰ ਇੱਕ ਸਤਰ ਸੰਭਾਲਦਾ ਹੈ: ਰੂਬਰਿਕ ਔਸਤ, ਪ੍ਰਤੀ ਕਾਲ ਕੀਮਤ, ਅਤੇ ਪਹਿਲੇ ਬਾਈਟ ਤੱਕ ਦਾ ਸਮਾਂ। ਰਨ ਮਾਡਲ ਰਜਿਸਟਰੀ ਪੰਨੇ ਤੋਂ ਕਤਾਰ ਵਿੱਚ ਲਗਾਏ ਜਾਂਦੇ ਹਨ ਅਤੇ cron ਵੱਲੋਂ ਚਲਾਏ ਜਾਂਦੇ ਹਨ।';
$string['settings:bench_judge_model'] = 'ਜੱਜ ਮਾਡਲ';
$string['settings:bench_judge_model_desc'] = 'ਉਹ ਮਾਡਲ ਜੋ ਜਵਾਬਾਂ ਨੂੰ ਅੰਕ ਦਿੰਦਾ ਹੈ। ਇਸ ਨੂੰ ਬਦਲਣ ਨਾਲ ਬਾਅਦ ਵਿੱਚ ਲਏ ਹਰ ਸਕੋਰ ਦਾ ਅਰਥ ਬਦਲ ਜਾਂਦਾ ਹੈ, ਇਸੇ ਕਰਕੇ ਹਰ ਰਨ ਵਰਤਿਆ ਗਿਆ ਜੱਜ ਅਤੇ ਉਹ ਪਲੱਗਇਨ ਰਿਲੀਜ਼ ਦਰਜ ਕਰਦਾ ਹੈ ਜਿਸ ਉੱਤੇ ਇਹ ਚੱਲਿਆ।';
$string['settings:bench_judge_provider'] = 'ਜੱਜ ਪ੍ਰਦਾਤਾ';
$string['settings:bench_judge_provider_desc'] = 'ਜਵਾਬਾਂ ਨੂੰ ਅੰਕ ਦੇਣ ਵਾਲੇ ਮਾਡਲ ਦਾ ਪ੍ਰਦਾਤਾ। ਇਸ ਨੂੰ ਮੁਕਾਬਲੇਬਾਜ਼ਾਂ ਦੇ ਸਮੂਹ ਤੋਂ ਬਾਹਰ ਰੱਖੋ: ਕੋਈ ਮਾਡਲ ਆਪਣੇ-ਆਪ ਨੂੰ ਅੰਕ ਨਹੀਂ ਦੇਣਾ ਚਾਹੀਦਾ।';
$string['settings:bench_min_quality_n'] = 'ਤੁਲਨਾਯੋਗਤਾ ਹੱਦ (ਅੰਕਿਤ ਆਈਟਮਾਂ)';
$string['settings:bench_min_quality_n_desc'] = 'ਕਿਸੇ ਸੰਭਾਲੇ ਰਨ ਕੋਲ ਘੱਟੋ-ਘੱਟ ਇੰਨੀਆਂ ਅੰਕਿਤ ਆਈਟਮਾਂ ਹੋਣੀਆਂ ਚਾਹੀਦੀਆਂ ਹਨ ਕਿ ਉਹ ਹਾਲੇ ਵੀ ਕਿਸੇ ਹੋਰ ਰਨ ਨਾਲ ਤੁਲਨਾ ਕੀਤਾ ਜਾ ਸਕੇ। ਹੱਦ ਤੋਂ ਹੇਠਾਂ ਵਾਲੇ ਰਨ ਰੱਖੇ ਅਤੇ ਦਿਖਾਏ ਜਾਂਦੇ ਹਨ, ਸਿਰਫ਼ ਹਵਾਲੇ ਵਜੋਂ ਲੇਬਲ ਕੀਤੇ, ਤਾਂ ਜੋ ਤਿੰਨ-ਪ੍ਰੌਂਪਟ ਵਾਲਾ smoke ਰਨ ਪੰਜਾਹ-ਪ੍ਰੌਂਪਟ ਵਾਲੇ ਨਤੀਜੇ ਤੋਂ ਕਦੇ ਅੱਗੇ ਨਾ ਨਿਕਲ ਸਕੇ। ਬਿਲਟ-ਇਨ ਡਿਫੌਲਟ ਵਰਤਣ ਲਈ 0 ਉੱਤੇ ਰੱਖੋ; 0 ਦੀ ਹੱਦ ਇਸ ਸੁਰੱਖਿਆ ਨੂੰ ਹੀ ਖਤਮ ਕਰ ਦੇਵੇਗੀ।';
$string['settings:embed_input_type_asymmetric'] = 'ਅਸਮਮਿਤ ਸਵਾਲ/ਦਸਤਾਵੇਜ਼ (ਸਿਫ਼ਾਰਸ਼ੀ)';
$string['settings:embed_input_type_mode'] = 'Embedding ਇਨਪੁੱਟ ਕਿਸਮ';
$string['settings:embed_input_type_mode_desc'] = 'ਸਿਰਫ਼ Voyage ਐਂਬੈਡਿੰਗ ਲਈ। Voyage ਪਾਠ ਨੂੰ ਇਸ ਆਧਾਰ ਉੱਤੇ ਵੱਖਰੇ ਢੰਗ ਨਾਲ ਪ੍ਰੋਜੈਕਟ ਕਰਦਾ ਹੈ ਕਿ ਉਹ ਸਵਾਲ ਹੈ ਜਾਂ ਦਸਤਾਵੇਜ਼। "ਅਸਮਮਿਤ" ਪ੍ਰਾਪਤੀ ਵੇਲੇ input_type=query ਅਤੇ ਸੂਚੀਕਰਨ ਵੇਲੇ input_type=document ਭੇਜਦਾ ਹੈ। ਵਿਕਰੇਤਾ ਦਾ ਇਹੀ ਮਕਸਦ ਹੈ ਅਤੇ ਇਸ ਸੰਗ੍ਰਹਿ ਉੱਤੇ ਇਹੀ ਸਭ ਤੋਂ ਵਧੀਆ ਮਾਪਿਆ ਗਿਆ: ਸਵਾਲ ਵਾਲੇ ਪਾਸੇ ਦਸਤਾਵੇਜ਼ ਪ੍ਰੋਜੈਕਸ਼ਨ ਵਰਤਣ ਨਾਲ recall ਵਿੱਚ 30.8 ਫ਼ੀਸਦ ਅੰਕਾਂ ਦਾ ਨੁਕਸਾਨ ਹੋਇਆ ਅਤੇ ਸਵਾਲ ਦੀ ਹਰ ਲੰਬਾਈ ਸ਼੍ਰੇਣੀ ਵਿੱਚ ਇਹ ਪਿੱਛੇ ਰਿਹਾ (2026-08-21, voyage-3.5, ਉਤਪਾਦਨ-ਵਰਗਾ ਸੈੱਟ)। "ਸਾਂਝੀ ਥਾਂ" ਦੋਹਾਂ ਪਾਸੇ input_type=document ਭੇਜਦੀ ਹੈ; ਇਹ ਮਾਪਣਯੋਗ ਤੌਰ ਉੱਤੇ ਮਾੜੀ ਪ੍ਰਾਪਤੀ ਕਰਦੀ ਹੈ ਅਤੇ ਸਿਰਫ਼ ਮਾਈਗ੍ਰੇਸ਼ਨ ਬੀਮੇ ਵਜੋਂ ਮੌਜੂਦ ਹੈ, ਕਿਉਂਕਿ ਇੱਕੋ ਪ੍ਰੋਜੈਕਸ਼ਨ ਹੋਣ ਨਾਲ ਸੰਗ੍ਰਹਿ ਨੂੰ ਦੁਬਾਰਾ ਐਂਬੈਡ ਕੀਤੇ ਬਿਨਾਂ ਸਵਾਲ ਮਾਡਲ ਬਦਲਿਆ ਜਾ ਸਕਦਾ ਹੈ। ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਮਾਈਗ੍ਰੇਸ਼ਨ ਦੇ ਵਿਚਕਾਰ ਨਾ ਹੋਵੋ, ਅਸਮਮਿਤ ਚੁਣੋ। ਇਸਨੂੰ ਬਦਲਣ ਲਈ ਮੁੜ-ਸੂਚੀਕਰਨ ਦੀ ਲੋੜ ਨਹੀਂ: ਸਿਰਫ਼ ਸਵਾਲ ਵਾਲੇ ਪਾਸੇ ਦਾ ਪ੍ਰੋਜੈਕਸ਼ਨ ਬਦਲਦਾ ਹੈ। ਇਹ ਅਸਮਮਿਤ ਮਾਡਲ ਜੋੜੀ ਨਹੀਂ ਹੈ (ਜਿਸ ਮਾਡਲ ਨਾਲ ਤੁਸੀਂ ਸਵਾਲ ਕਰਦੇ ਹੋ ਉਸ ਤੋਂ ਵੱਡੇ Voyage ਮਾਡਲ ਨਾਲ ਸੂਚੀਕਰਨ) — ਉਹ ਵੱਖਰੀ ਤਕਨੀਕ ਹੈ ਜੋ ਇਸ ਸੰਗ੍ਰਹਿ ਉੱਤੇ ਦੋ ਵਾਰ ਦੁਹਰਾਈ ਨਹੀਂ ਜਾ ਸਕੀ, ਅਤੇ ਉਹ ਸਵਾਲ ਮਾਡਲ ਸੈਟਿੰਗ ਦੁਆਰਾ ਨਿਯੰਤਰਿਤ ਹੁੰਦੀ ਹੈ, ਇਸ ਸੈਟਿੰਗ ਦੁਆਰਾ ਨਹੀਂ।';
$string['settings:embed_input_type_shared'] = 'ਸਾਂਝੀ ਥਾਂ (ਮਾਈਗ੍ਰੇਸ਼ਨ ਬੀਮਾ; ਪ੍ਰਾਪਤੀ ਮਾੜੀ)';
$string['settings:embed_migration_heading'] = 'Embedding ਮਾਡਲ ਮਾਈਗ੍ਰੇਸ਼ਨ';
$string['settings:embed_migration_heading_desc'] = 'embedding ਮਾਡਲ ਜਾਂ ਉਸ ਦੀ ਚੌੜਾਈ ਬਦਲਣ ਨਾਲ ਹਰ ਸੰਭਾਲਿਆ ਵੈਕਟਰ ਅਯੋਗ ਹੋ ਜਾਂਦਾ ਹੈ: ਪ੍ਰਾਪਤੀ ਵਿਧੀ ਕਿਸੇ ਵੱਖਰੀ embedding ਥਾਂ ਦੇ ਟੁਕੜਿਆਂ ਦੇ ਵਿਰੁੱਧ ਸਵਾਲ ਨੂੰ ਅੰਕ ਦੇਣ ਤੋਂ ਇਨਕਾਰ ਕਰਦੀ ਹੈ, ਸੋ ਕੋਰਸ ਖਰਾਬ ਨਤੀਜੇ ਦੇਣ ਦੀ ਥਾਂ ਕੁਝ ਵੀ ਨਹੀਂ ਦਿੰਦਾ। ਇਹ ਸੈਟਿੰਗਾਂ ਉਸ ਮਾਡਲ ਦਾ ਵਰਣਨ ਕਰਦੀਆਂ ਹਨ ਜਿਸ ਵੱਲ ਤੁਸੀਂ ਜਾ ਰਹੇ ਹੋ। ਫਿਰ ਕੋਰਸ RAG ਇੰਡੈਕਸ ਪੰਨੇ ਤੋਂ ਇੱਕ-ਇੱਕ ਕਰਕੇ ਦੁਬਾਰਾ embed ਕੀਤੇ ਜਾਂਦੇ ਹਨ, ਨਵੇਂ ਵੈਕਟਰ ਪੁਰਾਣਿਆਂ ਦੇ ਨਾਲ ਲਿਖੇ ਜਾਂਦੇ ਹਨ, ਅਤੇ ਉੱਪਰ ਦੀਆਂ ਸਰਗਰਮ ਸੈਟਿੰਗਾਂ ਪ੍ਰਾਪਤੀ ਚਲਾਉਂਦੀਆਂ ਰਹਿੰਦੀਆਂ ਹਨ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਆਪ ਉਨ੍ਹਾਂ ਨੂੰ ਨਹੀਂ ਬਦਲਦੇ।';
$string['settings:embed_migration_provider_inherit'] = 'ਉੱਪਰ ਸੰਰਚਿਤ ਪ੍ਰਦਾਤਾ ਵਰਤੋ';
$string['settings:embed_migration_target_apikey'] = 'ਟਾਰਗੇਟ ਪ੍ਰਦਾਤਾ API ਕੁੰਜੀ';
$string['settings:embed_migration_target_apikey_desc'] = 'ਸਿਰਫ਼ ਉਦੋਂ ਲੋੜੀਂਦੀ ਜਦੋਂ ਟਾਰਗੇਟ ਪ੍ਰਦਾਤਾ ਉੱਪਰ ਸੰਰਚਿਤ ਪ੍ਰਦਾਤਾ ਤੋਂ ਵੱਖਰਾ ਹੋਵੇ। ਖਾਲੀ ਦਾ ਮਤਲਬ ਮੌਜੂਦਾ embedding ਕੁੰਜੀ ਵਰਤਣਾ।';
$string['settings:embed_migration_target_dimensions'] = 'ਟਾਰਗੇਟ embedding ਚੌੜਾਈ';
$string['settings:embed_migration_target_dimensions_desc'] = 'ਮਾਈਗ੍ਰੇਸ਼ਨ ਦੌਰਾਨ ਮੰਗੀ ਜਾਣ ਵਾਲੀ ਵੈਕਟਰ ਚੌੜਾਈ। 0 ਦਾ ਮਤਲਬ ਮਾਡਲ ਦੀ ਮੂਲ ਚੌੜਾਈ। Voyage 256, 512, 1024 ਅਤੇ 2048 ਸਵੀਕਾਰ ਕਰਦਾ ਹੈ; ਜੋ ਚੌੜਾਈ ਮਾਡਲ ਨਹੀਂ ਦਿੰਦਾ, ਉਸ ਨੂੰ ਭੇਜਣ ਦੀ ਥਾਂ ਬੇਨਤੀ ਵਿੱਚੋਂ ਛੱਡ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ, ਨਹੀਂ ਤਾਂ ਤੁਹਾਨੂੰ ਮੰਗੀ ਹੋਈ ਚੌੜਾਈ ਦੀ ਥਾਂ ਚੁੱਪ-ਚਪੀਤੇ ਮੂਲ ਚੌੜਾਈ ਮਿਲ ਜਾਂਦੀ।';
$string['settings:embed_migration_target_model'] = 'ਟਾਰਗੇਟ embedding ਮਾਡਲ';
$string['settings:embed_migration_target_model_desc'] = 'ਮਾਈਗ੍ਰੇਸ਼ਨ ਦੌਰਾਨ embed ਕਰਨ ਲਈ ਵਰਤਿਆ ਜਾਣ ਵਾਲਾ ਮਾਡਲ ਨਾਮ, ਉਦਾਹਰਨ ਲਈ <code>voyage-4-large</code>। ਖਾਲੀ ਦਾ ਮਤਲਬ ਕੋਈ ਮਾਈਗ੍ਰੇਸ਼ਨ ਸੰਰਚਿਤ ਨਹੀਂ ਹੈ ਅਤੇ RAG ਇੰਡੈਕਸ ਪੰਨਾ ਕੋਈ ਨਹੀਂ ਪੇਸ਼ ਕਰਦਾ।';
$string['settings:embed_migration_target_provider'] = 'ਟਾਰਗੇਟ embedding ਪ੍ਰਦਾਤਾ';
$string['settings:embed_migration_target_provider_desc'] = 'ਉੱਪਰ ਪਹਿਲਾਂ ਹੀ ਸੰਰਚਿਤ ਪ੍ਰਦਾਤਾ ਦੇ ਅੰਦਰ ਹੀ ਮਾਈਗ੍ਰੇਟ ਕਰਨ ਲਈ ਖਾਲੀ ਛੱਡੋ।';
$string['settings:rerank_min_query_chars'] = 'Rerank: ਘੱਟੋ-ਘੱਟ ਸਵਾਲ ਲੰਬਾਈ';
$string['settings:rerank_min_query_chars_desc'] = 'ਇੰਨੇ ਜਾਂ ਇਸ ਤੋਂ ਘੱਟ ਅੱਖਰਾਂ ਵਾਲੇ ਸਵਾਲਾਂ ਲਈ re-ranker ਛੱਡ ਦਿਓ। ਛੋਟੇ ਸਵਾਲ ਕੀਵਰਡ ਵਰਗੇ ਹੁੰਦੇ ਹਨ ਅਤੇ ਦੋ-ਤਿੰਨ ਸ਼ਬਦਾਂ ਉੱਤੇ re-ranker cosine ਸਮਾਨਤਾ ਤੋਂ ਲਗਭਗ ਕੁਝ ਨਹੀਂ ਜੋੜਦਾ। RAG fixture ਸੈੱਟ ਉੱਤੇ ਮਾਪਿਆ: 50 ਉੱਤੇ ਰੋਕ ਲਗਾਉਣ ਨਾਲ 67.7% recall ਮਿਲਿਆ, ਜਦਕਿ ਸਦਾ-ਚਾਲੂ ਨਾਲ 67.2%, ਅਤੇ ਖਰਚ ਲਗਭਗ ਇੱਕ-ਤਿਹਾਈ। ਹਰ ਸਵਾਲ ਨੂੰ re-rank ਕਰਨ ਲਈ 0 ਸੈੱਟ ਕਰੋ। ਛੱਡੇ ਗਏ re-rank ਸੁਨੇਹਾ ਲੌਗ ਵਿੱਚ "[Rerank skipped: short_query]" ਵਜੋਂ ਦਰਜ ਹੁੰਦੇ ਹਨ, ਤਾਂ ਜੋ ਤੁਸੀਂ ਪੁਸ਼ਟੀ ਕਰ ਸਕੋ ਕਿ ਰੋਕ ਕੰਮ ਕਰ ਰਹੀ ਹੈ।';
$string['settings:spend_export_key'] = 'ਖਰਚ ਐਕਸਪੋਰਟ ਕੁੰਜੀ';
$string['settings:spend_export_key_desc'] = '<code>/local/ai_course_assistant/spend_export.php</code> ਉੱਤੇ ਮਹੀਨਾਵਾਰ AI-ਖਰਚ ਐਕਸਪੋਰਟ ਐਂਡਪੁਆਇੰਟ ਲਈ Bearer ਕੁੰਜੀ, ਜਿਸ ਤੋਂ ਖਰਚ ਡੈਸ਼ਬੋਰਡ ਮਹੀਨੇ ਵਿੱਚ ਇੱਕ ਵਾਰ ਡਾਟਾ ਖਿੱਚਦਾ ਹੈ। ਐਂਡਪੁਆਇੰਟ ਬੰਦ ਕਰਨ ਲਈ ਖਾਲੀ ਛੱਡੋ — ਫਿਰ ਇਹ ਹਰ ਬੇਨਤੀ ਨੂੰ 404 ਦਿੰਦਾ ਹੈ। ਕੁੰਜੀ ਸਿਰਫ਼ <code>Authorization: Bearer</code> ਹੈਡਰ ਵਿੱਚ ਸਵੀਕਾਰ ਕੀਤੀ ਜਾਂਦੀ ਹੈ, URL ਵਿੱਚ ਕਦੇ ਨਹੀਂ। ਇੱਕ ਲੰਮਾ ਰੈਂਡਮ ਮੁੱਲ ਬਣਾਓ; ਜਿਸ ਕੋਲ ਵੀ ਇਹ ਹੋਵੇ ਉਹ ਪੂਰੀ ਸਾਈਟ ਦਾ AI ਖਰਚ ਪੜ੍ਹ ਸਕਦਾ ਹੈ। ਹਰ ਸਫਲ ਐਕਸਪੋਰਟ ਪਲੱਗਇਨ ਆਡਿਟ ਲੌਗ ਵਿੱਚ ਦਰਜ ਹੁੰਦਾ ਹੈ।';
