$string['soapbox:feedback_pending'] = 'ਮੁਲਾਂਕਣ ਪੂਰਾ ਹੋਣ ਉੱਤੇ ਤੁਹਾਡੀ ਫੀਡਬੈਕ ਇੱਥੇ ਦਿਖਾਈ ਦੇਵੇਗੀ। ਆਮ ਤੌਰ ਉੱਤੇ ਕੁਝ ਮਿੰਟ ਲੱਗਦੇ ਹਨ। ਤੁਹਾਨੂੰ ਇਸ ਸਫ਼ੇ ਉੱਤੇ ਰੁਕਣ ਦੀ ਲੋੜ ਨਹੀਂ।';
$string['soapbox:feedback_toggle'] = 'ਮੇਰੀ ਫੀਡਬੈਕ ਦਿਖਾਓ';
