$string['coursesettings:how_it_works_desc'] = 'ਇੱਥੇ ਸੰਰਚਿਤ ਕੀਤੀਆਂ ਸੈਟਿੰਗਾਂ ਸਿਰਫ਼ ਇਸ ਕੋਰਸ ਲਈ ਗਲੋਬਲ ਡਿਫ਼ਾਲਟਾਂ ਨੂੰ ਓਵਰਰਾਈਡ ਕਰਦੀਆਂ ਹਨ। ਗਲੋਬਲ ਸੈਟਿੰਗ ਵਰਤਣ ਲਈ ਖੇਤਰ ਖਾਲੀ ਛੱਡੋ। ਇੱਥੋਂ ਦੀਆਂ ਤਬਦੀਲੀਆਂ ਹੋਰ ਕੋਰਸਾਂ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਨਹੀਂ ਕਰਦੀਆਂ।';
$string['coursesettings:inherit_global'] = 'ਗਲੋਬਲ ਵਿਰਾਸਤ ਵਿੱਚ ਲਵੋ ({$a})';
